      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Представьте, что у вас есть 100 000 рублей, спрятанные дома в шкафу. Через год купюры остались теми же, но в магазине на них можно купить на 10–15% меньше продуктов. Это и есть инфляция — процесс обесценивания денег и роста цен. Главная цель инвестиций на первом этапе — не «заработать миллионы за неделю», а заставить деньги расти быстрее инфляции, чтобы сохранить их покупательную способность.

📚 СЛОВАРЬ ТЕРМИНОВ
• Официальная инфляция (ИПЦ) — средний рост цен по стране, который считает Росстат по большой корзине товаров (от хлеба до стройматериалов).
• Личная инфляция — рост цен именно на те товары, которые покупаете лично вы (часто она выше официальной на 3–7%).
• Реальная доходность — доход от ваших вложений за вычетом инфляции и налогов. Если вклад дал 15%, а инфляция 12%, ваша реальная доходность — около 3%.

🟢 КОГДА ВХОДИТЬ (ПОКУПАТЬ АКТИВЫ)
• Когда у вас сформирована «финансовая подушка» (запас денег на 3–6 месяцев жизни на обычном банковском накопительном счете).
• В моменты, когда инфляция начинает разгоняться: лучше перекладывать свободные рубли в активы, которые защищают от роста цен (облигации с плавающим купоном — флоатеры, акции компаний-экспортеров или сырьевых гигантов, которые сами поднимают цены на свой товар).

🔴 КОГДА ВЫХОДИТЬ (УХОДИТЬ В ДЕНЬГИ)
• Не держите крупные суммы в наличных рублях дольше 1–2 месяцев без дела.
• Продавать защитные инфляционные активы (например, флоатеры) стоит тогда, когда инфляция достигла пика и начала устойчиво снижаться 2–3 месяца подряд — в этот момент выгоднее переложиться в активы с фиксированной высокой доходностью.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ РАЗГОНА ИНФЛЯЦИИ
• В магазинах уменьшается вес упаковок при старой цене («шринкфляция»: молоко по 900 мл вместо 1 литра).
• Банки начинают массово рекламировать вклады на короткий срок (3–6 месяцев) под рекордные проценты, но на 2–3 года дают ставку заметно ниже.
• Резко растут цены на грузоперевозки, бензин и базовую упаковку (картон, пластик) — через 1–2 месяца этот рост всегда перекладывается в ценники всех товаров на полках.
''',
