      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Биржа (например, Московская биржа — MOEX) — это огромный цифровой супермаркет, где встречаются продавцы и покупатели ценных бумаг. Но обычный человек не может прийти на биржу напрямую с улицы. По закону между вами и биржей стоит посредник — Брокер. А чтобы брокер не мог украсть ваши акции или обанкротиться вместе с ними, записи о том, что акции принадлежат именно вам, хранятся в отдельной защищенной организации — Депозитарии.

📚 СЛОВАРЬ ТЕРМИНОВ
• Брокер — лицензированная компания (часто при крупном банке), которая дает вам мобильное приложение и отправляет ваши заявки на биржу за небольшую комиссию (обычно 0,03% – 0,3% от сделки).
• Депозитарий — «электронный сейф и реестр», где записано: «Иванову И.И. принадлежит 10 акций Сбера». Даже если брокер закроется, ваши бумаги останутся за вами в депозитарии, и вы просто переведете их к другому брокеру.
• Эмитент — компания или государство, которые выпустили ценную бумагу (например, Лукойл, Сбербанк или Минфин РФ).
• Ликвидность — насколько быстро можно продать или купить бумагу по рыночной цене. Высокая ликвидность (Сбер, Газпром) — сделка проходит за долю секунды. Низкая ликвидность (мелкий завод 3-го эшелона) — покупателя можно ждать часами или придется сильно сбрасывать цену.

🟢 КОГДА ВХОДИТЬ (ПРАВИЛА БЕЗОПАСНОГО ВХОДА)
• Совершайте сделки только в основную торговую сессию (на Мосбирже для акций это с 10:00 до 18:40 по Москве). В это время на рынке максимальная ликвидность и самые честные цены.
• Для первых покупок выбирайте только высоколиквидные бумаги («голубые фишки» — топ-15 крупнейших компаний), где разница между ценой покупки и продажи минимальна.

🔴 КОГДА ВЫХОДИТЬ И ЧЕГО ИЗБЕГАТЬ
• Избегайте покупок и продаж на утренней (07:00–10:00) и вечерней (19:00–23:50) сессиях, если нет экстренной необходимости: крупных игроков (фондов и банков) там мало, и цена может быть искусственно завышена или занижена.
• Если брокер начинает задерживать вывод средств, навязывать странные комиссии или у него отзывают лицензию ЦБ — подавайте поручение на перевод ценных бумаг в депозитарий другого надежного брокера (продавать бумаги в убыток при этом не нужно).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если в неликвидной акции («третий эшелон») вдруг без новостей объем торгов за час вырастает в 20–50 раз — скорее всего, телеграм-каналы устраивают искусственный разгон («памп»), чтобы продать свои бумаги новичкам на вершине. Входить туда категорически нельзя.
''',
