      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Когда вы нажимаете кнопку «Купить» в приложении брокера, вы отправляете на биржу заявку (ордер). Все заявки покупателей и продавцов выстраиваются в очередь — эта таблица называется «Биржевой стакан». В верхней половине стакана стоят продавцы (красная зона — они хотят продать подороже), в нижней половине — покупатели (зеленая зона — хотят купить подешевле). Сделка происходит в ту секунду, когда кто-то соглашается на цену противоположной стороны.

📚 СЛОВАРЬ ТЕРМИНОВ
• Биржевой стакан (Order Book) — живая таблица заявок на покупку (Bid) и на продажу (Ask) с указанием цены и количества лотов.
• Спред (Spread) — разница между самой дешевой ценой продавца и самой дорогой ценой покупателя в стакане. В акциях Сбера спред — копейки (0,01%), а в редкой бумаге может быть 2–5%.
• Рыночная заявка (Market Order) — приказ брокеру: «Купи мне прямо сейчас по лучшей доступной цене в стакане». Исполняется мгновенно, но в неликвидной бумаге вы можете случайно скупить дорогие заявки и переплатить.
• Лимитная заявка (Limit Order) — приказ брокеру: «Купи мне не дороже 250 рублей». Заявка встает в стакан и ждет, пока цена дойдет до 250. Вы никогда не переплатите ни копейки.
• Лот (Lot) — минимальная «упаковка» акций на бирже. В одном лоте может быть 1 акция, 10, 100 или даже 10 000 акций.

🟢 КОГДА И КАК ВХОДИТЬ
• Всегда используйте **Лимитную заявку** при покупке любых облигаций и акций второго-третьего эшелона. Ставьте цену на уровне лучших покупателей или чуть ниже и спокойно ждите исполнения.
• Если в стакане со стороны покупателей стоит огромная заявка («плита» — например, на 100 000 лотов, тогда как на остальных уровнях по 500 лотов), это сильный уровень поддержки. Покупать имеет смысл на 1–2 копейки выше этой «плиты».

🔴 КОГДА И КАК ВЫХОДИТЬ
• Если нужно срочно выйти из падающей высоколиквидной акции — используйте рыночную заявку или лимитную заявку чуть ниже текущей цены.
• Если вы видите, что огромная «плита» продавца сверху не разбирается, а наоборот, опускается все ниже, поддавливая цену вниз — крупный игрок распродает позицию. Лучше выйти до того, как он обрушит цену.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ В СТАКАНЕ
• «Айсберг-заявка» (скрытый крупный игрок): в стакане висит скромная заявка на продажу 100 лотов по 300 руб. Ее покупают, но на ее месте мгновенно появляется новая на 100 лотов по 300 руб., и так десятки раз. Это робот крупного фонда незаметно разгружает огромную позицию (или набирает ее снизу). Идти против «айсберга» опасно.
''',
