      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Ключевая ставка Центрального Банка (ЦБ РФ) — это процент, под который главный банк страны дает деньги в долг коммерческим банкам (Сберу, ВТБ, Т-Банку) и принимает от них депозиты. Это «педаль газа и тормоза» для всей экономики.
• Когда инфляция высокая, ЦБ **повышает** ставку (жмет на тормоз): кредиты становятся дорогими, люди меньше тратят и несут деньги на вклады.
• Когда инфляция побеждена, а экономике нужен рост, ЦБ **снижает** ставку (жмет на газ): кредиты дешевеют, бизнес растет, вклады становятся невыгодными, и деньги текут на биржу.

📚 СЛОВАРЬ ТЕРМИНОВ
• Ключевая ставка — базовый процент стоимости денег в стране (устанавливается Советом директоров ЦБ 8 раз в год).
• Жесткая денежно-кредитная политика (ДКП) — период высоких ставок для борьбы с инфляцией.
• Мягкая ДКП — период низких ставок для стимулирования бизнеса.
• «Ястребиная» риторика ЦБ — жесткие заявления главы ЦБ о том, что ставку будут повышать или долго держать высокой.
• «Голубиная» риторика ЦБ — мягкие заявления о том, что инфляция замедляется и скоро ставку начнут снижать.

🟢 КОГДА И ЧТО ПОКУПАТЬ (СТРАТЕГИЯ ПО ЦИКЛУ СТАВКИ)
1. **Цикл повышения ставки (ставка растет с 8% до 18–21%):**
   • Покупаем: Фонды денежного рынка (LQDT, TMON), облигации-флоатеры (чей купон привязан к ставке ЦБ или RUONIA), акции компаний с огромной «кубышкой» наличных денег на счетах (Сургутнефтегаз, Интер РАО, Мосбиржа, Хэдхантер) — они сами зарабатывают миллиарды на высоких процентах в банках!
2. **Пик ставки (ЦБ перестал повышать ставку и намекает на будущее снижение):**
   • Это лучший момент на годы вперед для покупки длинных ОФЗ с постоянным купоном (на 10–15 лет) и надежных корпоративных облигаций с фиксированным купоном. Вы фиксируете огромную доходность на годы, а при снижении ставки сама цена этих облигаций взлетит на 20–40%.
3. **Цикл снижения ставки:**
   • Покупаем широкий рынок акций и компании роста (IT, ритейл), так как деньги из подешевевших банковских вкладов массово перетекают в акции.

🔴 КОГДА И ЧТО ПРОДАВАТЬ
• При первых признаках начала цикла повышения ставки ЦБ — немедленно продавайте длинные облигации с фиксированным купоном и акции закредитованных компаний (металлурги с большим долгом, застройщики, Сегежа, МТС, ВК, Мечел). Высокая ставка съест всю их прибыль через проценты по кредитам.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ РАЗВОРОТА СТАВКИ ЦБ
• Важнее самой цифры ставки — пресс-релиз ЦБ в 13:30 МСК в день заседания. Если ЦБ оставил ставку прежней, но убрал из текста фразу «допускает возможность дальнейшего повышения ставки» — это мощнейший сигнал разворота рынка вверх.
• Данные Росстата по недельной инфляции (выходят по средам в 19:00): если 4–5 недель подряд недельная инфляция держится ниже 0,1% — ЦБ готовится к смягчению.
''',
