      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Простой процент — это когда вы вложили 100 000 рублей под 15% годовых, каждый год получаете 15 000 рублей купонами или дивидендами и тратите их на кафе. Ваш капитал через 10 лет так и останется 100 000 рублей.
Сложный процент — это когда полученные 15 000 рублей вы НЕ тратите, а сразу докупаете на них новые облигации или акции (реинвестируете). На второй год проценты начисляются уже на 115 000 рублей, на третий — на 132 250 рублей. Через 10 лет под 15% с реинвестированием ваши 100 000 превратятся в 404 500 рублей, а через 20 лет — в 1 636 600 рублей без единого рубля дополнительных вложений!

📚 СЛОВАРЬ ТЕРМИНОВ
• Реинвестирование — покупка новых ценных бумаг на полученные дивиденды (от акций) и купоны (от облигаций).
• Капитализация процентов — прибавление полученного дохода к основному телу капитала, чтобы доход начал приносить новый доход.
• Правило 72 — быстрый способ в уме посчитать, за сколько лет ваш капитал удвоится при сложном проценте. Разделите число 72 на вашу годовую доходность в процентах. Например, при доходности 18% годовых капитал удваивается за: 72 / 18 = 4 года!

🟢 КОГДА ПРИМЕНЯТЬ (ТОЧКИ ВХОДА ДЛЯ РЕИНВЕСТИРОВАНИЯ)
• Купоны по облигациям приходят регулярно (раз в месяц, квартал или полгода). Реинвестируйте их сразу же в день поступления в те бумаги вашего портфеля, которые сейчас просели ниже своей справедливой цены.
• Дивиденды по акциям часто выгодно реинвестировать на следующий день после «дивидендной отсечки» (на дивидендном гэпе), когда акция дешевеет примерно на размер выплаченного дивиденда.

🔴 ЧТО РАЗРУШАЕТ СЛОЖНЫЙ ПРОЦЕНТ (КОГДА ОСТАНАВЛИВАТЬСЯ)
• Главный враг сложного процента — крупные убытки (просадки на 50% и более). Чтобы отыграть падение на 50%, оставшемуся капиталу нужно вырасти на 100%! Поэтому защита от катастрофических убытков важнее погони за сверхдоходностью.
• Переходите от реинвестирования к жизни на пассивный доход (снятию купонов и дивидендов) только тогда, когда размер капитала достиг вашей финальной финансовой цели.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если вы используете биржевые фонды (БПИФы на акции, облигации или денежный рынок), фонд автоматически реинвестирует приходящие внутрь него купоны и дивиденды. При этом фонд по закону не платит налог 13% с дивидендов и купонов внутри себя — это ускоряет сложный процент.
''',
      keyRules: [
        'Правило 72: разделите 72 на годовой процент доходности — получите число лет до удвоения капитала.',
        'Первые 3–5 лет сложный процент кажется медленным, но после 7–10 лет график капитала уходит резко вверх по экспоненте.',
        'Не прерывайте работу сложного процента выводом мелких сумм на бытовые траты.'
      ],
      question: 'По «Правилу 72», за сколько лет ваш капитал удвоится, если вы инвестируете под 12% годовых и реинвестируете все купоны?',
