      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
У каждого инструмента на бирже своя роль в вашем портфеле — как у игроков в футбольной команде: есть нападающие (зарабатывают много в хорошие времена) и есть защитники с вратарем (спасают капитал в кризис).
1. **Облигации (Защита и предсказуемость):** Вы даете деньги в долг государству или компании под точный процент (купон) на точный срок. В конце срока вам обязаны вернуть номинал (обычно 1000 руб.).
2. **Акции (Нападение и рост):** Вы покупаете долю в бизнесе. Здесь никто не обещает вернуть деньги в конкретную дату, но если бизнес растет, вы получаете долю прибыли (дивиденды) и рост цены самой акции.
3. **Фонды / БПИФ (Готовая корзина):** Один пай фонда сразу содержит десятки акций, облигаций или инструментов денежного рынка.
4. **Золото и Валютные инструменты (Страховка от девальвации):** Защищают капитал, когда национальная валюта (рубль) резко слабеет.

📚 СЛОВАРЬ ТЕРМИНОВ
• Долговой рынок — рынок облигаций (вы кредитор).
• Долевой рынок — рынок акций (вы совладелец бизнеса).
• Девальвация — ослабление курса рубля по отношению к мировым валютам (доллару, юаню, евро).
• Корреляция — связь между движениями активов. Если акции падают, а золото растет — у них отрицательная (обратная) корреляция, что идеально для баланса портфеля.

🟢 КОГДА КАКОЙ КЛАСС ПОКУПАТЬ
• **В кризис, панику и обвал на бирже:** Покупаем качественные акции на дне (когда все боятся) и длинные надежные облигации.
• **В период спокойствия и крепкого рубля:** Постепенно (на 5–10% портфеля) докупаем золото и замещающие/валютные облигации, пока они дешевые.
• **В период неопределенности и высоких ставок:** Держим до 40–60% в фондах денежного рынка и флоатерах.

🔴 КОГДА ПРОДАВАТЬ И ПЕРЕКЛАДЫВАТЬСЯ
• Когда рубль резко обвалился, а в новостях все бегут менять рубли в обменниках на пике паники — это момент ПРОДАВАТЬ часть подорожавшего золота или валютных активов и перекладывать прибыль в подешевевшие рублевые акции и ОФЗ.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ ПЕРЕТОКА КАПИТАЛА
• Если индекс акций (IMOEX) перестал расти на хороших новостях, а объемы торгов в фондах денежного рынка и коротких облигациях бьют рекорды — крупные игроки тихо фиксируют прибыль в акциях и уходят в защиту перед коррекцией.
''',
      keyRules: [
