      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
На финансовом рынке действует жесткий закон физики: **чем выше обещанная доходность, тем выше риск потерять деньги**.
Эталоном «безрисковой доходности» в рублях считаются государственные облигации РФ (ОФЗ) и вклады в крупнейших системно значимых банках. Допустим, сейчас ОФЗ дают 16% годовых.
• Если надежная крупная компания (РЖД, Газпром) хочет занять деньги, она вынуждена предложить чуть больше — например, 17,5–18% годовых.
• А если вам предлагают облигацию неизвестной микрофинансовой конторы или строительной фирмы под 28–32% годовых — этот дополнительный процент (премия за риск) платится за то, что компания с высокой вероятностью может обанкротиться и вообще не вернуть ваш долг!

📚 СЛОВАРЬ ТЕРМИНОВ
• Безрисковая ставка — доходность по самым надежным гособлигациям (ОФЗ). От нее отсчитывается выгода всех остальных вложений.
• Премия за риск (Risk Premium) — дополнительная доходность сверх ставки ОФЗ, которую инвестор требует за то, что берет на себя риск падения цены или банкротства компании.
• Дефолт — отказ или неспособность должника выплатить купон или вернуть основной долг по облигации.
• ВДО (Высокодоходные облигации) — облигации небольших или сильно закредитованных компаний с высокой ставкой купона и высоким риском дефолта (на Западе их прямо называют «мусорными облигациями» — Junk Bonds).

🟢 КОГДА ОПРАВДАН ПОВЫШЕННЫЙ РИСК (СИГНАЛЫ ВХОДА)
• Брать акции вместо ОФЗ имеет смысл тогда, когда ожидаемая дивидендная доходность и рост прибыли компании дают премию хотя бы +4..+6% годовых сверх доходности ОФЗ, либо когда рынок акций сильно упал и торгуется дешево.
• Если берете высокодоходные облигации (ВДО), выделяйте на одного эмитента не более 1–2% от всего портфеля, чтобы дефолт одной компании не нанес ущерба.

🔴 КОГДА ВЫХОДИТЬ (СИГНАЛЫ ОПАСНОСТИ)
• Если доходность к погашению какой-то корпоративной облигации внезапно подскочила на 10–15% выше среднерыночной (например, все облигации дают 18%, а эта вдруг стала давать 35% из-за падения ее цены в стакане) — это НЕ щедрый подарок! Это рынок узнал о проблемах компании и бежит из нее перед дефолтом. Срочно проверяйте новости и выходите.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ БУДУЩЕГО ДЕФОЛТА КОМПАНИИ
• Из компании внезапно увольняется финансовый директор (CFO) или главный бухгалтер за 1–2 месяца до крупной выплаты по долгам.
• Компания задерживает публикацию квартального финансового отчета или меняет крупного аудитора на никому не известную фирму.
• Налоговая служба (ФНС) блокирует счета компании за неуплату налогов (эта информация открыта и появляется раньше официального дефолта на бирже).
''',
      keyRules: [
