      title: 'Урок 8. Психология рынка: Страх, Жадность и синдром FOMO',
      category: 'Психология',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
90% новичков теряют деньги на бирже не из-за плохой математики, а из-за эмоций. Человеческий мозг устроен эволюционно так, чтобы бежать туда, куда бежит вся толпа:
• Когда акция выросла на 100%, о ней кричат из каждого утюга, друзья хвастаются прибылью — у человека включается **Жадность и FOMO** (страх упущенной выгоды). Он покупает на самом пике («на хаях»).
• Затем крупные фонды, которые покупали дешево полгода назад, начинают продавать свои акции этой восторженной толпе. Цена падает на 20–30%. Новичок испытывает **Страх и Панику**, продает на самом дне («на лоях»), фиксируя реальный убыток, и клянется больше не подходить к бирже.

📚 СЛОВАРЬ ТЕРМИНОВ
• FOMO (Fear Of Missing Out) — синдром упущенной выгоды: мучительное желание запрыгнуть в уходящий поезд (купить резко растущую акцию по любой цене).
• Паник-сейл (Panic Sale) — массовая распродажа бумаг толпой по любым низким ценам на фоне пугающих новостей.
• «Покупать на хаях, продавать на лоях» (от англ. High — максимум, Low — минимум) — классическая ошибка эмоционального инвестора.
• Усреднение — докупка подешевевшей качественной бумаги частями для снижения средней цены покупки в портфеле.

🟢 КОГДА ВХОДИТЬ (ПРАВИЛО ПРОТИВОПОЛОЖНОСТИ ТОЛПЕ)
• Знаменитое правило Уоррена Баффета: **«Бойтесь, когда другие жадничают, и будьте жадными, когда другие боятся»**.
• Лучшие точки входа за последние 15 лет возникали в дни максимальной паники, когда в новостях писали «рынок умер», а сильные компании (Сбер, Лукойл, Фосагро) падали на 20–40% за несколько дней без разрушения самого бизнеса.
• Входите лесенкой: разделите сумму на 3–4 части и покупайте по мере падения, не пытаясь угадать самую нижнюю копейку.

🔴 КОГДА ВЫХОДИТЬ
• Когда об акции начинают говорить люди, далекие от финансов (таксисты, родственники на кухне, популярные блогеры), а график летит вертикально вверх без откатов — это стадия **Эйфории**. Начинайте продавать позицию частями (по 25–30%), забирая прибыль со стола.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ ЭЙФОРИИ И ПАНИКИ
• **Признак пика (пора продавать):** Рекордное число новых открытых брокерских счетов физлиц за месяц; статьи в СМИ с заголовками «Акции компании Х никогда не упадут»; огромный объем покупок с заемными деньгами («с плечом»).
• **Признак дна (пора покупать):** Массовое принудительное закрытие позиций брокерами (Маржин-коллы) — на графике это выглядит как огромная свеча вниз с гигантским объемом торгов, после которой цена вдруг перестает падать даже на плохих новостях (продавцы просто закончились!).
''',
      keyRules: [
        'Никогда не покупайте акцию в день, когда она взлетела на +10..+20% на шумной новости — дайте эмоциям остыть 2–3 дня.',
        'Составляйте план сделки ДО покупки: по какой цене берете, по какой докупаете и при каком условии выходите.',
