      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
«Не кладите все яйца в одну корзину» — на языке финансов это называется **Диверсификацией**. Даже самая надежная на вид компания может столкнуться с аварией на производстве, санкциями, новым налогом или ошибкой руководства.
Но просто купить 10 разных акций недостаточно: если вы купили 5 нефтяных компаний и 5 банков, то при падении цен на нефть и кризисе в экономике упадут все 10! Настоящая диверсификация работает на трех уровнях:
1. **По классам активов:** акции + облигации + денежный рынок + золото.
2. **По отраслям:** нефть, IT, ритейл (продукты питания), финансы, удобрения, электроэнергетика.
3. **По валютам дохода:** компании, зарабатывающие в рублях внутри страны + экспортеры, зарабатывающие в валюте.

📚 СЛОВАРЬ ТЕРМИНОВ
• Диверсификация — распределение капитала между не связанными друг с другом активами для снижения риска.
• Ребалансировка — периодическое (раз в полгода или год) возвращение долей вашего портфеля к изначальному плану.
• Аллокация активов (Asset Allocation) — процентное соотношение классов активов в вашем портфеле (например: 50% облигации, 35% акции, 15% золото/валюта).

🟢 КАК ДЕЛАТЬ РЕБАЛАНСИРОВКУ (АВТОМАТИЧЕСКАЯ ПОКУПКА ДЕШЕВОГО)
Допустим, вы решили держать **50% в акциях** и **50% в облигациях**.
• Через полгода рынок акций сильно вырос, и теперь в вашем портфеле акции занимают **65%**, а облигации — **35%**.
• Вы делаете ребалансировку: продаете подорожавшие акции (15%) и на эти деньги докупаете отставшие облигации (или направляете новые пополнения счета только в облигации), возвращая пропорцию 50/50.
• А если акции обвалились и стали занимать **35%**, а облигации **65%** — вы продаете часть стабильных облигаций и покупаете подешевевшие акции на дне!
Таким образом, ребалансировка **механически заставляет вас продавать дорого и покупать дешево** без участия эмоций.

🔴 КОГДА РЕБАЛАНСИРОВКА НЕ НУЖНА (ОШИБКИ)
• Не делайте ребалансировку каждую неделю — вы просто потеряете деньги на комиссиях брокера и налогах. Оптимальный шаг: раз в 6–12 месяцев или когда доля какого-то класса активов отклонилась от плана более чем на 10%.
• Никогда не увеличивайте долю падающей отдельной компании выше 10–15% портфеля, если ее падение вызвано разрушением бизнеса, а не общим падением рынка.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ ПЕРЕКОСА ПОРТФЕЛЯ
• Если изменение цены одной компании за день меняет стоимость всего вашего портфеля более чем на 2–3% — у вас опасная концентрация в одной бумаге.
• Оптимальное число акций в портфеле частного инвестора — от 8 до 15 компаний из разных секторов. Если бумаг больше 25–30, вы физически не сможете следить за их отчетами.
''',
