      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Многие новички смотрят только на зеленые цифры прибыли в приложении, забывая, что за каждое движение на бирже кто-то берет маленькую плату. Если совершать по 20 сделок в день, комиссии могут незаметно «съесть» половину вашего годового дохода.

📚 СЛОВАРЬ ТЕРМИНОВ (ЗА ЧТО И КОМУ МЫ ПЛАТИМ)
1. **Комиссия за сделку (Брокерская + Биржевая):** Списывается каждый раз, когда вы покупаете или продаете бумагу. На базовых тарифах для новичков она может быть высокой (0,3% за покупку + 0,3% за продажу = 0,6% за круг!). На продвинутых тарифах без абонентской платы — около 0,04% – 0,05%.
2. **Абонентская плата за тариф:** Некоторые тарифы берут 200–300 рублей в месяц, если была хотя бы одна сделка. Если ваш портфель всего 10 000 рублей, плата 300 руб./мес. заберет у вас 36% годовых!
3. **Комиссия за управление фондом (TER — Total Expense Ratio):** Если вы покупаете БПИФ (паевой фонд), управляющая компания ежедневно удерживает из стоимости пая небольшую комиссию (от 0,2% до 2% в год). Вы не видите ее как отдельное списание — она уже зашита в цену пая.
4. **Плата за маржинальную торговлю (перенос плеча):** Если вы случайно купили бумаг больше, чем у вас было своих рублей (взяли в долг у брокера), за каждую ночь переноса долга брокер списывает огромные проценты (часто 25–35% годовых).

🟢 КАК ОПТИМИЗИРОВАТЬ ПРИ ВХОДЕ
• Перед первой сделкой зайдите в настройки профиля у брокера и проверьте свой тариф: выберите тариф **без фиксированной ежемесячной абонентской платы** и с комиссией за сделку не выше 0,05% – 0,1%.
• Сразу отключите в настройках приложения тумблер **«Маржинальная торговля» (Торговля с плечом / Непокрытые позиции)** — это защитит вас от случайной покупки в кредит у брокера.

🔴 КОГДА ВЫХОДИТЬ ИЗ НЕВЫГОДНЫХ ИНСТРУМЕНТОВ
• Если вы выбираете между двумя одинаковыми биржевыми фондами (например, на денежный рынок или индекс Мосбиржи), всегда проверяйте в паспорте фонда «Вознаграждение УК и общие расходы». Если один фонд берет 0,3% в год, а другой за то же самое 1,8% в год — продавайте дорогой фонд и переходите в дешевый.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ СКРЫТЫХ ПОТЕРЬ
• Часто брокеры рекламируют «Покупку фондов без комиссии брокера!». Это правда, комиссию за саму кнопку «Купить» они не возьмут. Но внутри своего фирменного фонда управляющая компания этого же банка может списывать по 1,5–2% ежегодно за управление. Всегда смотрите внутреннюю комиссию фонда (TER).
''',
