      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Новички часто пугаются: «Я продал акции в четверг, вижу деньги на брокерском счете, нажимаю "Вывести на банковскую карту", а приложение пишет: Доступно к выводу 0 рублей! Или предлагает вывести с комиссией за кредит! Меня обманули?».
Нет! На Московской бирже (как и на большинстве мировых бирж) действует режим расчетов **Т+1** (Trade + 1 рабочий день).
Когда вы нажали кнопку «Продать», сделка зафиксировалась мгновенно, и на эти виртуальные деньги вы можете тут же купить другую акцию. Но **настоящая юридическая поставка бумаг в депозитарии и перевод живых денег между банками происходят на следующий рабочий день (Т+1)**.

📚 СЛОВАРЬ ТЕРМИНОВ
• Т+1 — режим расчетов, при котором фактическая поставка ценных бумаг и зачисление денег для вывода происходят на следующий рабочий день после заключения сделки (Т — день сделки, +1 — один рабочий день).
• Дивидендная отсечка в режиме Т+1 — чтобы попасть в реестр акционеров и получить дивиденды, нужно купить акцию минимум за 1 рабочий день ДО даты закрытия реестра.

🟢 КОГДА ПОКУПАТЬ С УЧЕТОМ Т+1
• Если компания закрывает реестр на дивиденды в понедельник, то последний день для покупки акции с дивидендами — **пятница** (так как суббота и воскресенье — нерабочие дни для расчетов депозитария).
• Покупать новые бумаги внутри брокерского счета после продажи старых можно сразу же в ту же секунду — ждать следующий день не нужно.

🔴 КОГДА ПРОДАВАТЬ, ЕСЛИ НУЖНЫ НАЛИЧНЫЕ ДЕНЬГИ
• Если вам понадобятся наличные деньги на банковской карте в пятницу вечером или на выходных — продать акции или облигации на бирже нужно **в четверг** до окончания торговой сессии! Тогда в пятницу утром расчеты Т+1 завершатся, и вы бесплатно выведете деньги на карту.
• Если вы продадите бумаги в пятницу, расчеты Т+1 завершатся только в **понедельник** (следующий рабочий день).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ И ЛОВУШКИ
• Некоторые брокеры предлагают кнопку «Моментальный вывод сразу после продажи». Будьте осторожны: юридически ваши деньги от биржи придут только завтра (по Т+1), поэтому сегодня брокер выдает вам **свои деньги в кредит на одну ночь** и берет за это скрытую комиссию! Лучше просто подождать до утра следующего рабочего дня и вывести бесплатно.
''',
