📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
По закону Центральный Банк РФ делит всех частных инвесторов на две категории: **Неквалифицированные («неквалы»)** — это все новички по умолчанию, и **Квалифицированные («квалы»)** — опытные участники с крупным капиталом или профильным образованием.
Это сделано не для того, чтобы кого-то обидеть, а чтобы защитить новичка от покупки сверхсложных и опасных инструментов (например, структурных нот или облигаций со сложными условиями), где можно потерять 100% денег, даже не поняв почему.

📚 СЛОВАРЬ ТЕРМИНОВ
• Неквалифицированный инвестор — статус по умолчанию при открытии счета. Сразу без тестов доступны: все государственные облигации (ОФЗ), акции из котировальных списков Мосбиржи (Сбер, Лукойл, Яндекс и др.), надежные корпоративные облигации с высоким кредитным рейтингом и биржевые паевые фонды (БПИФ).
• Тестирование ЦБ — короткие бесплатные тесты в приложении каждого брокера (обычно 7 вопросов: 3 об опыте и 4 по сути инструмента). Сдав тест, «неквал» получает доступ к флоатерам, акциям вне основных списков, ВДО, фьючерсам или маржинальной торговле. Попытки сдачи бесплатны и не ограничены!
• Квалифицированный инвестор («Квал») — статус, который присваивается по заявлению при выполнении одного из условий ЦБ (например, наличие активов на счетах от установленного законом порога — 12/24 млн руб., либо большой оборот сделок за год, либо высшее экономическое образование/сертификат).

🟢 КОГДА И КАКИЕ ТЕСТЫ СДАВАТЬ
• В первые недели обязательно пройдите в приложении брокера два бесплатных теста:
  1. **«Облигации со структурным доходом / переменным купоном (флоатеры)»** — чтобы иметь возможность покупать надежные флоатеры, защищающие от роста ставки ЦБ.
  2. **«Облигации с низким кредитным рейтингом» и «Акции, не включенные в котировальные списки»** — чтобы понимать риски бумаг второго-третьего эшелона.

🔴 ЧЕГО ИЗБЕГАТЬ ДАЖЕ ПОСЛЕ СДАЧИ ТЕСТОВ
• Сдача теста на «Маржинальную торговлю» (плечи) и «Производные финансовые инструменты» (фьючерсы и опционы) открывает доступ к инструментам повышенного риска. Не торгуйте ими на реальные деньги, пока не пройдете профильные модули нашей академии и не отработаете навыки в симуляторе.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если менеджер банка звонит вам и настойчиво предлагает «помочь оформить статус квала, чтобы купить эксклюзивную структурную ноту под 30% годовых» — немедленно кладите трубку. Банки часто продают сложные структурные продукты с огромными скрытыми комиссиями, перекладывая весь рыночный риск на клиента.
''',
