      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Все компании на бирже делятся по размеру, надежности и объему торгов на три группы — «эшелона»:
1. **Первый эшелон («Голубые фишки»):** 15–20 крупнейших гигантов экономики (Сбербанк, Лукойл, Роснефть, Газпром, Татнефть, Новатэк, Фосагро, Норникель, Полюс, Яндекс). Здесь огромная ликвидность, узкий спред, регулярные отчеты и максимальная прозрачность.
2. **Второй эшелон:** Крепкие, часто быстрорастущие компании среднего размера (Совкомфлот, Магнит, Интер РАО, Ростелеком, Группа Позитив, Ренессанс Страхование и др.). Они могут расти быстрее гигантов, но колебания цен (волатильность) здесь выше.
3. **Третий эшелон:** Небольшие региональные заводы, сбытовые компании и малоликвидные бумаги. Торгов там мало, а цена может взлететь на +40% за час и так же рухнуть обратно без всяких новостей.

📚 СЛОВАРЬ ТЕРМИНОВ
• Голубые фишки (Blue Chips) — акции самых крупных, надежных и ликвидных компаний рынка (термин пришел из покера, где голубые фишки имели самую высокую ценность).
• Капитализация компании — рыночная стоимость всей компании целиком (Цена одной акции, умноженная на общее количество всех выпущенных акций).
• Волатильность — размах колебаний цены вверх и вниз. Низкая волатильность — цена ходит на 0,5% в день; высокая волатильность — цена скачет на 5–15% в день.
• Памп и Дамп (Pump & Dump) — мошенническая схема в 3-м эшелоне: организаторы заранее скупают дешевую неликвидную акцию, затем в телеграм-каналах вбрасывают фейковую «инсайдерскую новость», толпа скупает бумагу, разгоняя цену (Pump), а организаторы продают свои акции толпе, обрушивая график в пол (Dump).

🟢 КОГДА И В КАКОЙ ЭШЕЛОН ВХОДИТЬ
• **База портфеля (70–80% всех акций)** всегда должна состоять из прибыльных «голубых фишек» и лидеров второго эшелона.
• В начале выхода рынка из кризиса первыми всегда начинают расти именно «голубые фишки» (Сбер, Лукойл), так как крупные фонды заходят сначала в самые ликвидные бумаги.
• Второй эшелон догоняет лидеров во второй фазе роста рынка — когда голубые фишки уже выросли на 20–30% и инвесторы ищут недооцененные идеи.

🔴 КОГДА ВЫХОДИТЬ И ЧЕГО НЕ ТРОГАТЬ
• **Никогда не покупайте акции 3-го эшелона по сигналам из телеграм-каналов!** В 99% случаев вы станете тем человеком, об которого закроют сделку организаторы «пампа».
• При первых признаках кризиса или повышения ставки ЦБ первыми сокращайте бумаги 2-го и 3-го эшелонов: в панику из них исчезают покупатели, и продать их без огромной скидки становится невозможно.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ «ПАМПА» В 3-М ЭШЕЛОНЕ
• Акция неизвестного областного завода, у которой полгода дневной оборот торгов был 2 миллиона рублей, вдруг в 11:00 утра показывает оборот 500 миллионов рублей и рост +25%, при этом на официальном сайте раскрытия информации (e-disclosure.ru) нет ни одной новости. Это 100% искусственный разгон.
''',
