📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Как понять за 5 секунд, что сегодня происходит на рынке: всё растет или всё падает? Для этого существуют **Биржевые индексы** — это «средняя температура по больнице», рассчитанная по корзине самых главных ценных бумаг.
На российском рынке у каждого инвестора перед глазами должны быть два главных градусника:
1. **Индекс Мосбиржи (IMOEX)** — показывает состояние рынка **акций** (в него входят около 45 крупнейших компаний России в рублях, где наибольший вес у Сбера, Лукойла и Газпрома).
2. **Индекс гособлигаций (RGBI)** — показывает состояние рынка **облигаций** (рассчитывается по ценам длинных ОФЗ с фиксированным купоном).

📚 СЛОВАРЬ ТЕРМИНОВ
• IMOEX — главный рублевый индекс акций Московской биржи (не путать с акциями самой компании «Московская биржа», у которой тикер MOEX!).
• IMOEX2 — тот же индекс Мосбиржи, но учитывающий утреннюю и вечернюю торговые сессии.
• MCFTR — индекс Мосбиржи **полной доходности** (учитывает не только цены акций, но и выплаченные компаниями дивиденды). На российском рынке дивиденды огромны, поэтому долгосрочно MCFTR растет намного сильнее обычного IMOEX.
• RGBI (Russian Government Bond Index) — индекс цен государственных облигаций РФ. Когда RGBI падает — доходности облигаций растут (рынок ждет высокой ставки ЦБ). Когда RGBI разворачивается и растет — рынок ждет снижения ставки ЦБ!

🟢 КАК ИСПОЛЬЗОВАТЬ ИНДЕКСЫ ДЛЯ ВХОДА
• **Главный секрет профессионалов:** Индекс облигаций **RGBI** почти всегда разворачивается раньше рынка акций! Долговой рынок умнее и осторожнее. Если после долгого падения индекс RGBI перестал обновлять минимумы и начал устойчиво расти 2–3 недели подряд — значит, крупные банки поверили в пик инфляции и ставки ЦБ. Это лучший сигнал для набора длинных ОФЗ и подготовки к покупке акций.

🔴 СИГНАЛЫ ТРЕВОГИ (КОГДА СОКРАЩАТЬ РИСКИ)
• **Медвежья дивергенция индексов:** Если индекс акций IMOEX продолжает расти на оптимизме физлиц, а индекс гособлигаций RGBI в это же время камнем падает вниз — ждите беды! Падение RGBI означает рост ставок в экономике, и очень скоро рынок акций тоже развернется вниз вслед за облигациями.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если значение индекса RGBI опускается ниже 100–105 пунктов — исторически это зоны экстремально высоких ставок и перепроданности гособлигаций (такое бывает раз в несколько лет), где покупка длинных ОФЗ приносила максимальную прибыль на горизонте 1,5–2 лет.
''',
