📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Инвестировать без четкого плана — это как сесть в поезд, не зная, на какую станцию вам нужно. Если вам понадобятся деньги через 6 месяцев на покупку машины или ремонт квартиры, вкладывать их в акции **категорически запрещено**: рынок акций в любой момент может уйти в просадку на год, и вам придется фиксировать убыток.
Каждой финансовой цели соответствует свой срок (горизонт) и свой набор инструментов.

📚 СЛОВАРЬ ТЕРМИНОВ
• Горизонт инвестирования — срок, в течение которого вы точно НЕ будете забирать вложенные деньги с биржи.
• Финансовая подушка безопасности — неприкосновенный запас денег в размере 3–6 ваших месячных расходов, который лежит на банковском накопительном счете или в фонде денежного рынка с мгновенным доступом.
• Риск-профиль — ваша психологическая и финансовая готовность терпеть временное падение стоимости портфеля.
  - **Консервативный:** не готов видеть минус вообще (до 85–100% облигации и денежный рынок, 0–15% акции).
  - **Умеренный (Сбалансированный):** готов переждать временную просадку ради доходности выше инфляции (50–60% облигации, 30–40% акции, 10% золото/валюта).
  - **Агрессивный:** долгий горизонт от 5 лет, готов спокойно докупать акции при падении рынка на 30% (70–80% акции, 20–30% облигации/кэш для докупок).

🟢 КАК ВЫБРАТЬ СТРАТЕГИЮ ПЕРЕД ВХОДОМ (ПО СРОКАМ)
1. **Горизонт до 1 года:** Только банковские вклады, накопительные счета, фонды денежного рынка (LQDT) и короткие облигации с погашением ровно к вашей дате. Никаких акций и длинных ОФЗ!
2. **Горизонт 1 – 3 года:** Облигации с фиксированным купоном (со сроком погашения не дальше вашего горизонта), флоатеры, до 20–30% дивидендных акций и золота.
3. **Горизонт от 3 – 5 лет и более:** Полноценный портфель с высокой долей акций, длинных ОФЗ (на пике ставок) и использованием налоговых льгот (ИИС-3, льгота долгосрочного владения ЛДВ от 3 лет).

🔴 КОГДА ВЫХОДИТЬ ИЗ РИСКОВЫХ АКТИВОВ ПО ПЛАНУ
• **Правило сокращения риска по мере приближения цели:** Если вы копили 5 лет на покупку квартиры в акциях и длинных облигациях, то за **12–18 месяцев до даты покупки квартиры** начинайте плавно продавать акции на росте и перекладывать капитал в короткие облигации и денежный рынок. Так внезапный кризис за месяц до сделки с квартирой не разрушит ваши накопления.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ НЕПРАВИЛЬНОГО РИСК-ПРОФИЛЯ
• Если вы проверяете котировки в приложении брокера каждые 15 минут и плохо спите ночью из-за падения портфеля на 3% — доля акций в вашем портфеле слишком велика для вашей нервной системы. Уменьшите долю акций в пользу облигаций до того уровня, при котором вы спите спокойно.
''',
