      category: 'Облигации',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Облигация — это официальная долговая расписка, которая торгуется на бирже. Покупая облигацию, вы становитесь кредитором (как банк), а государство или компания становятся вашим должником.
У каждой классической облигации есть три железных параметра, известных заранее:
1. **Номинал** — сумма долга, которую вам обязаны вернуть в конце срока (в России почти всегда **1000 рублей**).
2. **Купон** — процентные выплаты, которые должник платит вам за пользование деньгами (обычно 2, 4 или 12 раз в год).
3. **Дата погашения** — конкретный день календаря, когда облигация исчезает, а на ваш брокерский счет автоматически возвращается ровно 1000 рублей номинала + последний купон.

📚 СЛОВАРЬ ТЕРМИНОВ
• Номинал (Face Value) — базовая стоимость облигации при выпуске и погашении (стандарт Мосбиржи — 1000 руб.).
• Рыночная цена облигации — текущая цена в биржевом стакане. На бирже она пишется **в процентах от номинала**! Например, цена `92,5%` означает `925 рублей`, а цена `103,2%` означает `1032 рубля`.
• Дисконт — покупка облигации дешевле номинала (ниже 100%, например по 850 руб.). При погашении вам всё равно вернут полные 1000 руб.!
• Премия — покупка облигации дороже номинала (выше 100%, например по 1050 руб.). При погашении вернут только 1000 руб., поэтому переплачивать выше номинала нужно крайне осторожно.

🟢 КОГДА ВХОДИТЬ (ПОКУПАТЬ)
• Идеальная покупка консервативного инвестора — качественная облигация, торгующаяся **ниже номинала (по 80–97%)** или около **100%**, со сроком погашения, который точно совпадает с вашей финансовой целью (например, через 1,5 года).
• Покупая бумагу по 850 руб. с купоном 100 руб. в год, вы получаете двойную выгоду: регулярные купоны + гарантированный рост тела бумаги с 850 до 1000 руб. к дате погашения.

🔴 КОГДА ВЫХОДИТЬ (НЕ ДЕРЖАТЬ ДО ПОГАШЕНИЯ)
• Если вы купили облигацию по 850 руб. с погашением через 3 года, а из-за снижения ставки ЦБ она уже через полгода выросла в цене до 1020 руб. — часто выгоднее продать ее досрочно, забрав трехлетний рост цены за полгода, и переложить деньги в другие активы.
• Никогда не покупайте короткую облигацию (до погашения меньше 6 месяцев) по цене сильно выше 100% (например, по 1040 руб.) — при погашении вам вернут ровно 1000 руб., и убыток в 40 руб. на теле бумаги съест ваши купоны.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если за 1–2 месяца до даты погашения надежные облигации всегда подтягиваются к цене 99,5% – 100%, а какая-то бумага за месяц до погашения вдруг торгуется по 75% – 85% — рынок сомневается, что у компании есть деньги на возврат номинала. Не гонитесь за «легкими 20% за месяц», риск дефолта критический.
''',
      keyRules: [
