      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
На банковском вкладе действует жестокое правило: если вы положили деньги на год, но забрали их за 3 дня до конца срока, банк сжигает все ваши проценты за 362 дня.
В облигациях всё работает честно благодаря механизму **НКД (Накопленного купонного дохода)**.
Допустим, облигация платит купон 60 рублей раз в полгода (180 дней). Значит, каждый день на нее «капает» ровно по `60 / 180 = 0,33 рубля` процентов.
Если вы продержали облигацию 100 дней и решили ее продать, **покупатель вашей облигации обязан из своего кармана прямо в момент сделки выплатить вам накопленный купон за эти 100 дней (33 рубля)** сверх цены самой облигации! А через оставшиеся 80 дней этот новый покупатель получит от эмитента весь полный купон (60 рублей). Никто не теряет ни одного дня доходности!

📚 СЛОВАРЬ ТЕРМИНОВ
• НКД (Накопленный купонный доход) — часть купона, накопившаяся с момента прошлой выплаты до сегодняшнего дня.
• «Чистая» цена облигации — цена самой бумаги в стакане без учета НКД (например, 950 руб.).
• «Грязная» (полная) цена сделки — реальная сумма, которая спишется с вашего счета при покупке: `Чистая цена + НКД + Комиссия брокера`.

🟢 КАК УЧИТЫВАТЬ НКД ПРИ ПОКУПКЕ (ТОЧКИ ВХОДА)
• Для доходности нет разницы, в какой день покупать облигацию — с маленьким НКД или большим, так как уплаченный продавцу НКД вернется вам в составе ближайшего купона.
• **Но есть важный налоговый нюанс!** Когда вам приходит купон от эмитента, брокер удерживает налог **13% со ВСЕЙ суммы купона**, даже если вы купили облигацию вчера и уплатили 99% этого купона прошлому владельцу в виде НКД! (Этот переплаченный налог вернется только в конце года при сальдировании, если вы продадите или погасите бумагу).
• **Вывод:** Выгоднее покупать облигации **в первые дни ПОСЛЕ выплаты очередного купона**, когда НКД обнулился и равен 0–2 рублям!

🔴 КОГДА ПРОДАВАТЬ С УЧЕТОМ НКД
• Если вам нужно продать облигацию, которая выросла в цене, и до выплаты купона осталось всего 2–3 дня — иногда выгоднее продать ее **ДО выплаты купона** (забрав весь купон через НКД от покупателя), если по этой бумаге у вас применяется льгота на продажу или вы не хотите замораживать деньги на ожидание зачисления купона от депозитария (купон от эмитента идет на счет от 1 до 5 рабочих дней, а НКД при продаже вы получаете мгновенно!).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• В день выплаты купона НКД в карточке облигации резко обнуляется (`НКД = 0 руб.`), а сам купон поступает на ваш брокерский счет не в ту же секунду, а через 1–3 рабочих дня. Не пугайтесь, если в день выплаты НКД исчез, а купон еще в пути — это стандартная процедура перевода денег через Национальный расчетный депозитарий (НРД).
''',
