      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
В приложении брокера у одной и той же облигации могут быть написаны три разные цифры: купон 8%, текущая доходность 11% и доходность к погашению 18%. На какую смотреть?
Давайте разберем на простом примере: облигация номиналом **1000 руб.** платит купон **80 руб. в год** (это 8% от номинала). Но из-за роста ставки ЦБ ее цена в стакане упала до **750 руб.**, а погашение ровно через **2 года**.

📚 СЛОВАРЬ ТЕРМИНОВ (3 ВИДА ДОХОДНОСТИ)
1. **Номинальная купонная доходность (8%):** Считается от номинала 1000 руб. (`80 / 1000 = 8%`). Если вы покупаете бумагу не по 1000 руб., эта цифра для вас бесполезна.
2. **Текущая купонная доходность (10,67%):** Показывает, сколько процентов годовых дают купоны от вашей **реальной цены покупки** (`80 руб. купона / 750 руб. цены = 10,67% годовых`). Это ваш живой денежный поток на руки каждый год.
3. **Эффективная доходность к погашению (YTM — Yield to Maturity):** Главный показатель в приложении брокера! Он складывает:
   • Все купоны до конца срока (по 80 руб. в год);
   • Плюс прибыль от возврата номинала в конце срока (вы купили за 750 руб., а вернут 1000 руб. = +250 руб. сверху!);
   • Плюс предполагает, что каждый полученный купон вы **реинвестируете** под ту же самую доходность!

🟢 НА КАКУЮ ДОХОДНОСТЬ СМОТРЕТЬ ПРИ ВХОДЕ
• **Если вы копите капитал и реинвестируете все купоны:** Смотрите на **Доходность к погашению (YTM)**, сравнивая выпуски одинаковой надежности и одинакового срока.
• **Если вы живете на купоны (снимаете их на жизнь):** Смотрите на **Текущую купонную доходность**! Бумага с крошечным купоном 6% и ценой 600 рублей даст высокую доходность к погашению через 10 лет, но живых денег на карту сейчас будет приносить совсем мало (всего 10% текущих). Для жизни на доход выбирайте бумаги с высоким текущим купоном.

🔴 ЛОВУШКА YTM (КОГДА ЦИФРА В ПРИЛОЖЕНИИ ОБМАНЫВАЕТ)
• Формула YTM наивно считает, что если сегодня вы купили бумагу с доходностью 20% на 5 лет, то все 5 лет вы сможете реинвестировать приходящие купоны тоже под 20%. Но если через год ставка ЦБ снизится до 10%, новые купоны вы сможете вкладывать только под 10%!
• Поэтому на пике высоких ставок ЦБ реальная доходность за весь срок окажется на 1–2% ниже расчетной YTM, если только вы не берете длинную бумагу с большим дисконтом (где основная прибыль зашита в росте тела от 600 до 1000 руб.).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если у облигации в приложении брокера стоит YTM 22%, но в карточке написано **«Доходность к оферте»** через 3 месяца, а не к погашению — будьте внимательны: через 3 месяца компания имеет право изменить купон на 0,1% годовых! (Об этом мы подробно поговорим в уроке про Оферты).
''',
