📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
**ОФЗ** — это облигации, которые выпускает Министерство финансов Российской Федерации. Это самый надежный рублевый инструмент на бирже: государство отвечает по ним всем бюджетом страны и правом печатать рубли.
Когда вы открываете список ОФЗ в приложении, вы видите странные коды, например: `ОФЗ 26238` или `ОФЗ 29025`. Первые две цифры кода и буквы названия сразу говорят профессионалу, как устроена эта бумага!

📚 РАСШИФРОВКА ВСЕХ ВИДОВ ОФЗ
1. **ОФЗ-ПД (Постоянный Доход — коды начинаются на `26...`, например 26238, 26244, 26248):**
   • Размер купона жестко зафиксирован в рублях в день выпуска и **не меняется до самого погашения** (даже через 10–15 лет!).
   • Именно эти бумаги сильнее всего падают в цене при росте ставки ЦБ и сильнее всего **взлетают в цене (+20..+40%) при снижении ставки ЦБ**.
2. **ОФЗ-ПК (Переменный Купон / Флоатеры — коды начинаются на `29...`, например 29024, 29025):**
   • Купон не фиксирован, а привязан к межбанковской ставке **RUONIA** (она всегда ходит почти один в один за ключевой ставкой ЦБ).
   • Ставка ЦБ выросла до 20% — ваш купон автоматически вырос до ~20%! При этом цена самой бумаги в стакане почти не колеблется и стоит около 100% (1000 руб.).
3. **ОФЗ-ИН (Индексируемый Номинал / Линкеры — коды начинаются на `52...`, например 52002, 52004):**
   • Купон маленький (2,5% годовых), НО сам **номинал облигации ежедневно увеличивается на величину официальной инфляции (ИПЦ Росстата)**! Если инфляция за год 12%, номинал вырастет на 12%, и при погашении вам вернут проиндексированный номинал.
4. **ОФЗ-АД (Амортизация Долга — коды начинаются на `46...`):**
   • Редкие выпуски, где номинал 1000 руб. возвращают не в самом конце, а частями по графику на протяжении нескольких лет.

🟢 КОГДА КАКОЙ ТИП ОФЗ ПОКУПАТЬ (ЧЕТКАЯ СТРАТЕГИЯ)
• **Ставка ЦБ растет или инфляция разгоняется:** Покупаем **ОФЗ-ПК (`29...`)** — получаем максимальный текущий купон и полную защиту цены от падения.
• **Ставка ЦБ достигла пика и готовится к развороту вниз:** Продаем часть ОФЗ-ПК и перекладываемся в длинные **ОФЗ-ПД (`26...`)** на 10–15 лет. Фиксируем высокий купон на десятилетие и зарабатываем десятки процентов на росте тела облигации!
• **Опасаетесь многолетней высокой инфляции при искусственно заниженной ставке ЦБ:** Покупаем **ОФЗ-ИН (`52...`)**, когда они торгуются с дисконтом к своему текущему номиналу.

🔴 КОГДА ВЫХОДИТЬ
• Никогда не держите длинные **ОФЗ-ПД (`26...`)**, если ЦБ начинает новый цикл повышения ключевой ставки — их рыночная цена может упасть на 20–35% за год.
• Выходите из **ОФЗ-ПК (`29...`)**, когда ЦБ активно снижает ставку: их купон будет быстро худеть вслед за ставкой, а цена выше 100–101% не вырастет.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Минфин каждую среду проводит аукционы по размещению новых ОФЗ для крупных банков. Если в среду Минфин размещает длинные ОФЗ-ПД на 100+ млрд рублей без скидки при огромном спросе банков — крупные игроки уверены в скором снижении ставки ЦБ.
''',
