      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Почему при повышении ставки ЦБ старые облигации с постоянным купоном падают в цене, а при снижении ставки — растут?
Представьте: у вас на руках старая ОФЗ с купоном **70 рублей в год (7%)** при номинале 1000 руб. Вдруг ЦБ поднимает ставку до **16%**, и теперь любой вклад и новая облигация дают **160 рублей в год**.
Купит ли кто-нибудь у вас вашу старую облигацию с купоном 70 рублей за 1000 рублей? Конечно нет! Чтобы покупатель согласился ее взять, **цена вашей облигации в стакане должна упасть** (например, до 550–600 рублей) так, чтобы ее итоговая доходность сравнялась с новыми 16% на рынке!
А когда ставка ЦБ снова упадет с 16% до 8%, цена этой облигации взлетит обратно с 600 до 950–1000 рублей!
Насколько сильно изменится цена облигации при изменении ставки ЦБ на 1%, показывает параметр **Модифицированная дюрация**.

📚 СЛОВАРЬ ТЕРМИНОВ
• Дюрация (Duration) — эффективный срок до полного возврата вложенных в облигацию денег (с учетом не только даты погашения номинала, но и скорости возврата денег через купоны или оферту). Измеряется в годах или днях.
• Модифицированная дюрация (чувствительность к ставке) — показывает, **на сколько процентов изменится цена облигации при изменении рыночных ставок на 1% в противоположную сторону**!
• **Формула расчета:** `Изменение цены ≈ - Дюрация (в годах) × Изменение ставки (%)`.

🟢 КАК ИСПОЛЬЗОВАТЬ ДЮРАЦИЮ ДЛЯ ВХОДА (ПРИМЕР РАСЧЕТА)
Возьмем длинную ОФЗ-ПД (например, ОФЗ 26238), у которой дюрация составляет около **7,5 лет**, а цена сейчас **520 рублей (52%)**.
• Если за следующие 1,5 года ключевая ставка и доходности на рынке снизятся на **4%** (например, с 16% до 12%), то по формуле дюрации цена этой ОФЗ вырастет примерно на:
  `7,5 × 4% = +30%` только за счет роста тела бумаги! Плюс сверху вы будете получать ~13,5% годовых текущими купонами! Итого: **более 40% доходности на самом надежном государственном инструменте без риска банкротства!**
• **Правило входа:** Перед началом цикла снижения ставки ЦБ выбирайте ОФЗ-ПД с **максимальной дюрацией (от 5 до 8 лет)**.

🔴 КАК ИСПОЛЬЗОВАТЬ ДЮРАЦИЮ ДЛЯ ЗАЩИТЫ (ВЫХОД)
• Если вы видите угрозу роста инфляции и повышения ставки ЦБ, немедленно сокращайте дюрацию портфеля!
• Перекладывайтесь в короткие облигации с **дюрацией менее 0,5 – 1 года** (или во флоатеры, у которых процентная дюрация близка к нулю). Если у облигации дюрация 0,5 года, то даже при скачке ставки на +4% ее цена просядет всего на `0,5 × 4% = 2%`, которые быстро перекроются купоном.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Обратите внимание: у 15-летней облигации с купоном 10% дюрация равна не 15 годам, а всего ~6–7 годам, потому что больше половины ваших денег вернется к вам раньше срока через регулярные купоны. Всегда смотрите в карточке брокера именно строку **«Дюрация»**, а не просто «Срок до погашения».
''',
