      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Помимо государственных флоатеров (ОФЗ-ПК), на бирже торгуются сотни **корпоративных флоатеров** от крупнейших компаний и банков (Газпром нефть, РЖД, МТС, ВЭБ.РФ, Совкомфлот, Альфа-Банк, Россети).
Чем они лучше ОФЗ-ПК? Тем, что компании платят **премию (надбавку) сверх ставки ЦБ или RUONIA**!
Например, формула купона такого флоатера выглядит так: **`Ключевая ставка ЦБ + 1,5%`** (или `RUONIA + 2,0%`). Если ставка ЦБ 18%, то ваш купон автоматически равен `18% + 1,5% = 19,5% годовых`, а выплаты часто приходят **каждый месяц**!

📚 СЛОВАРЬ ТЕРМИНОВ
• Флоатер (Floater) — облигация с плавающим купоном, привязанным к рыночному индикатору.
• RUONIA (Ruble Overnight Index Average) — ставка, под которую крупнейшие банки дают друг другу рубли в долг на одну ночь. Она почти равна Ключевой ставке ЦБ (обычно отличается на 0,1% – 0,4%).
• Спред (премия) флоатера — фиксированная надбавка эмитента к базовой ставке (например, `+1,4%` или `+2,5%`).
• Временной лаг купона — задержка при расчете купона. У старых флоатеров купон рассчитывался по средней ставке за прошлые 3 или 6 месяцев. У современных флоатеров ставка берется ежедневно (с лагом всего 5–7 дней), поэтому при повышении ставки ЦБ ваш купон вырастает в тот же день!

🟢 КОГДА И КАК ВЫБИРАТЬ ФЛОАТЕРЫ (ТОЧКИ ВХОДА)
• При выборе корпоративного флоатера проверяйте 3 вещи:
  1. **Кредитный рейтинг эмитента:** Не ниже `AA-` / `AA` / `AAA` (надежные гиганты). Брать флоатер слабой компании с рейтингом `BB` опасно: когда ставка ЦБ вырастет до 20%, слабая компания просто не выдержит выплаты такого купона и объявит дефолт!
  2. **База привязки:** Лучше выбирать привязку напрямую к **Ключевой ставке ЦБ (КС)** с ежедневным расчетом и выплатой купона 12 раз в год (ежемесячно).
  3. **Цена в стакане:** Старайтесь покупать флоатеры по цене **не выше 100,0% – 100,5%** от номинала (а еще лучше — на просадках по 97–99%).

🔴 КОГДА ВЫХОДИТЬ ИЗ ФЛОАТЕРОВ
• Если на рынке начинается паника из-за нехватки ликвидности у банков или фондов, даже самые надежные корпоративные флоатеры с рейтингом `AAA` могут временно просесть в цене с 100% до 94–96% (так как фонды распродают их, чтобы добыть кэш). Продавать их на такой панике нельзя — к погашению они вернутся к 100%.
• Планово выходить из флоатеров нужно тогда, когда они торгуются около 100%, а ЦБ готов начать цикл снижения ключевой ставки — перекладывайте эти деньги в облигации с фиксированным купоном.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если новые выпуски корпоративных флоатеров с рейтингом `AA` выходят на биржу со всё более высокой премией к ставке ЦБ (например, полгода назад давали `КС + 1,1%`, а сегодня новые выпуски той же компании дают `КС + 2,3%`), то старые флоатеры с маленькой премией (`+1,1%`) обязательно упадут в цене до 96–98%, чтобы выровнять доходность. В этот момент выгоднее брать либо новый выпуск на размещении, либо подешевевший старый выпуск с дисконтом!
''',
