      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Это самая частая и болезненная ловушка для начинающих в облигациях!
Вы видите корпоративную облигацию со сроком погашения в **2030 году** и шикарным купоном **18% годовых**. Но в карточке бумаги мелким шрифтом написано: **«Дата оферты: 15 ноября 2026 года»**, а купоны в календаре прописаны только до ноября 2026 года, а дальше стоят прочерки!
Что такое **Оферта**? Это юридическая точка пересмотра условий внутри жизни облигации. За 1–2 недели до даты оферты компания-должник официально объявляет новый размер купона на следующие полгода-год.
И по закону компания имеет полное право сказать: **«Ребята, мне ваши деньги в долг больше не нужны, поэтому после 15 ноября я устанавливаю новый купон в размере 0,01% годовых (10 копеек в год)! Кто не согласен — подавайте заявление своему брокеру на выкуп облигации по номиналу 1000 руб. в дни оферты!»**.
Если новичок не следил за датой оферты и **не подал заявку брокеру**, окно оферты закрывается! На следующий день цена этой облигации с купоном 0,01% обваливается в стакане с 1000 до **300–400 рублей**, и продать ее без огромного убытка уже невозможно!

📚 СЛОВАРЬ ТЕРМИНОВ
• **Put-оферта (безотзывная оферта — право инвестора):** Самый частый вид. Компания назначает новый купон до даты оферты. Если новый купон вам не нравится, вы **имеете право предъявить облигацию к выкупу за 100% номинала (1000 руб.)**, но для этого **ОБЯЗАТЕЛЬНО нужно подать заявку через брокера** в строго отведенное окно (обычно за 3–7 рабочих дней до даты оферты)! Автоматически бумага НЕ погасится!
• **Call-оферта (отзывная оферта — право компании):** Компания имеет право в дату оферты **принудительно** выкупить у всех инвесторов свои облигации по 1000 руб., даже если вы не хотели их продавать (происходит автоматически, как обычное погашение).

🟢 КАК ПРАВИЛЬНО РАБОТАТЬ С ОФЕРТАМИ (СИГНАЛЫ ВХОДА)
• Если вы новичок и не хотите следить за календарем — выбирайте облигации **БЕЗ ОФЕРТЫ** (где купоны жестко прописаны до самого конца срока погашения).
• Если вы покупаете облигацию с Put-офертой, воспринимайте **дату оферты как реальную дату погашения**! Сразу при покупке поставьте себе напоминание в телефон за **10 дней до даты оферты**.

🔴 КАК ВЫЙТИ ПО ОФЕРТЕ БЕЗ ПОТЕРЬ
За 7–10 дней до Put-оферты компания публикует приказ о новом купоне:
1. **Если новый купон рыночный и высокий (например, был 17%, а сделали 18,5%):** Ничего делать не нужно! Просто продолжайте держать облигацию дальше, ее цена в стакане останется около 1000 руб.
2. **Если новый купон заниженный (или вы просто хотите забрать деньги):**
   • **Способ А:** Подайте в чате/меню брокера поручение на участие в оферте (у некоторых брокеров это платно — 300–500 руб., проверяйте тариф!).
   • **Способ Б (лайфхак для небольших сумм):** Если компания еще не объявила плохой купон, проще **продать облигацию прямо в биржевом стакане за 10–14 дней до оферты** по цене ~99,8–100%, чтобы не платить комиссию брокеру за подачу заявления на оферту и не ждать возврата денег!

🕵️ КОСВЕННЫЕ ПРИЗНАКИ «ЗЛОЙ ОФЕРТЫ»
• Если компания затягивает объявление нового купона до самого последнего законного часа перед открытием окна приема заявок на оферту — очень высок риск, что она назначит символический купон (0,1% – 1%), рассчитывая на то, что невнимательные физлица не успеют подать заявки на выкуп. В таких случаях продавайте бумагу в стакане заранее!
''',
