      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
По обычной облигации вам весь срок платят только купоны, а все 1000 рублей номинала возвращают одним куском в самый последний день.
Но многие компании и регионы (муниципальные облигации областей и городов) выпускают облигации **с Амортизацией долга**.
Это похоже на выплату ипотеки: вместе с очередным купоном компания возвращает вам на счет **кусочек самого номинала** (например, по 10% или 25% от 1000 рублей).
• Была облигация номиналом **1000 руб.** и купоном **16% (160 руб. в год)**.
• Прошла первая амортизация 25%: вам на брокерский счет пришли купон + **250 рублей живыми деньгами**!
• Теперь оставшийся номинал вашей облигации стал равен **750 рублей**. И следующие купоны (16% годовых) будут начисляться уже на оставшиеся **750 рублей** (то есть купон в рублях станет 120 руб. в год)!

📚 СЛОВАРЬ ТЕРМИНОВ
• Амортизация долга — выплата основного долга (номинала облигации) частями по заранее известному графику вместе с купонами.
• Непогашенный (текущий) номинал — остаток номинала облигации после прошедших амортизационных выплат (может быть 800 руб., 500 руб., 200 руб.).

🟢 КОГДА ВЫГОДНО ПОКУПАТЬ БУМАГИ С АМОРТИЗАЦИЕЙ
• **В период цикла повышения ставок ЦБ:** Амортизация — ваш друг! Вам регулярно возвращают части номинала по 100%, и вы тут же перекладываете эти освободившиеся деньги в новые облигации под еще более высокий процент. Кроме того, амортизация сильно снижает риск дефолта (должник гасит долг плавно, а не ищет миллиарды в один день) и уменьшает дюрацию бумаги.
• Если бумага с близкой амортизацией торгуется с большим дисконтом (например, по 90% от номинала), то при каждой выплате амортизации эту часть долга вам гасят **ровно по 100% номинала**, что ускоряет вашу прибыль!

🔴 КОГДА АМОРТИЗАЦИЯ НЕВЫГОДНА (ОШИБКИ)
• **На пике ставок перед их снижением:** Если вы хотите зафиксировать высокий купон 18–20% на 5–10 лет вперед, бумага с быстрой амортизацией вам помешает — компания быстро вернет вам тело долга, и возвращенные деньги придется реинвестировать уже под низкие ставки (10–12%).
• **Никогда не покупайте облигацию с близкой амортизацией дороже 100% номинала!** Если вы купили бумагу по 105%, а через месяц она гасит 50% номинала по 100%, вы мгновенно получите 5% убытка на погашенную половину!

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Иногда новичок видит в стакане облигацию по цене **400 рублей** и радостно покупает ее, думая: «Ух ты, скидка 60% от 1000 рублей!». А потом открывает карточку бумаги и видит, что ее цена в процентах равна **100%**, просто компания уже выплатила 600 рублей по амортизации в прошлые годы, и **текущий номинал бумаги равен 400 рублям**! Всегда смотрите на цену **в процентах от номинала** и на строку «Текущий номинал».
''',
