      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Как понять, вернет ли компания ваш долг через 3 года, если вы не профессиональный аудитор?
Для этого в России работают официальные аккредитованные ЦБ рейтинговые агентства — главные из них **АКРА** и **«Эксперт РА»** (а также НКР и НРА). Их аналитики проверяют всю бухгалтерию компании, ее долги, кредиты, суды и присваивают ей **Кредитный рейтинг** по буквенной шкале от `AAA` (максимальная надежность) до `C` и `D` (дефолт).

📚 ШКАЛА КРЕДИТНЫХ РЕЙТИНГОВ (ОТ ЛУЧШЕГО К ОПАСНОМУ)
1. **Высший эшелон (`ruAAA`, `AA+`, `AA`, `AA-`):**
   • Гиганты экономики и госкомпании (Сбер, Газпром, Лукойл, РЖД, Роснефть, Фосагро, Атомэнергопром, Россети). Вероятность внезапного дефолта близка к нулю. Основа консервативного портфеля.
2. **Крепкий средний класс (`A+`, `A`, `A-`):**
   • Надежные, устойчивые компании второго эшелона. Дают премию +1,5..+3% годовых к ОФЗ. Подходят для разумного увеличения доходности портфеля.
3. **Умеренно-рискованный сегмент (`BBB+`, `BBB`, `BBB-`):**
   • Компании, чувствительные к кризисам и высокой ставке ЦБ. Доля одной такой компании в портфеле — не более 3–5%.
4. **Спекулятивный сегмент / ВДО (`BB+`, `BB`, `B`, `CCC`):**
   • Высокодоходные («мусорные») облигации. Высокий риск кассового разрыва и дефолта при ухудшении экономики.
5. **Преддефолт и Дефолт (`C`, `RD`, `D`):**
   • Компания уже не платит по долгам.

🟢 ПРАВИЛА ВХОДА ПО РЕЙТИНГАМ
• **Формула спокойного сна для облигационного портфеля:**
  - Минимум **70%** портфеля облигаций: ОФЗ + компании с рейтингом `AAA` и `AA`.
  - До **20–25%**: компании с рейтингом `A+`, `A`, `A-`.
  - Не более **5–10%** (и только при желании): бумаги с рейтингом `BBB` (разбитые по 1–2% на выпуск).
• Всегда смотрите не только на буквы рейтинга, но и на **Прогноз агентства** рядом с ним: «Стабильный», «Позитивный» или «Негативный». Покупка бумаги с рейтингом `A-` и «Позитивным» прогнозом выгоднее: когда ей повысят рейтинг до `A+`, цена ее облигаций вырастет!

🔴 КОГДА НЕМЕДЛЕННО ВЫХОДИТЬ
• Если рейтинговое агентство меняет прогноз компании на **«Негативный»** или ставит статус **«Рейтинг под наблюдением»**, либо понижает рейтинг сразу на 2–3 ступени (например, с `A` до `BBB-` — как это было с компанией «Сегежа» или «М.Видео» при росте их долгов) — **продавайте облигацию в тот же день**, не дожидаясь дальнейшего обвала цены!

🕵️ КОСВЕННЫЕ ПРИЗНАКИ МАНИПУЛЯЦИИ РЕЙТИНГОМ
• Если компания несколько лет получала рейтинг у строгого агентства **АКРА** или **Эксперт РА**, но вдруг отказывается от их услуг («отзывает рейтинг по инициативе эмитента») и переходит в менее крупное агентство, где ей рисуют букву повыше — это тревожный красный флаг! Скорее всего, старое агентство собиралось понизить ей рейтинг из-за ухудшения отчетности.
''',
