      moduleTitle: 'Модуль 2. Облигации: от ОФЗ до корпоративных выпусков',
      title: 'Урок 25. Высокодоходные облигации (ВДО): правила выживания и признаки скорого дефолта',
      category: 'Риски облигаций',
      readingTimeMinutes: 8,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
**ВДО (Высокодоходные облигации)** — это облигации небольших компаний (лизинговые фирмы, региональные застройщики, агрохолдинги, микрофинансовые компании, оптовики) с рейтингом от `BBB-` до `B`, которые предлагают купоны на **5–10% выше ставки ЦБ**.
Почему они платят так много? Потому что крупные банки не дают им дешевые кредиты без твердого залога. И они идут на биржу занимать деньги у частных инвесторов.
В спокойные годы экономики ВДО приносят отличную прибыль. Но в период **высокой ключевой ставки ЦБ** в секторе ВДО начинается волна банкротств (дефолтов). Один дефолт сжигает 100% вложенных в бумагу денег, что уничтожает повышенные купоны сразу по 10 другим компаниям!

📚 СЛОВАРЬ ТЕРМИНОВ
• Технический дефолт — просрочка выплаты купона или номинала. По закону у компании есть **10 рабочих дней**, чтобы всё-таки найти деньги и расплатиться. В 90% случаев в ВДО технический дефолт перерастает в настоящий.
• Полноценный дефолт — невыплата долга по истечении 10 рабочих дней. Торги бумагой останавливаются или переводятся в спецрежим, начинаются многолетние суды и банкротство, где физлица обычно получают 0–5 копеек на рубль.
• Кассовый разрыв — ситуация, когда бизнес в целом работает, но прямо сегодня на счете нет живых денег, чтобы погасить выпуск облигаций.
• Ковенанты — особые условия в договоре облигации, при нарушении которых (например, просрочка по кредиту в банке — кросс-дефолт) держатели облигаций имеют право потребовать досрочного возврата всего долга.

🟢 КОГДА МОЖНО ВХОДИТЬ В ВДО (ЖЕЛЕЗНЫЕ ПРАВИЛА)
• Входить в ВДО можно **только в фазе снижения или стабильно низкой ключевой ставки ЦБ**, когда малому бизнесу легко перекредитоваться.
• **Правило диверсификации ВДО:** На весь сектор ВДО — не более 10% вашего общего капитала, а на **одного эмитента ВДО — строго не более 1% портфеля**!
• Лучшая точка входа в качественную ВДО (рейтинг `BBB`/`BB+`) — **на первичном размещении по номиналу 1000 руб.** При высоком купоне в первые дни торгов цена часто уходит на 101–102%, где спекулянты фиксируют быструю прибыль.

🔴 КОГДА КАТЕГОРИЧЕСКИ НЕЛЬЗЯ ПОКУПАТЬ (И НУЖНО БЕЖАТЬ)
• В период, когда ставка ЦБ держится выше 16–18% дольше полугода — **полностью откажитесь от ВДО с рейтингом ниже `A-`**. Нагрузка по процентам убивает слабых должников.
• Немедленно продавайте ВДО по любой цене, если цена бумаги в стакане без общерыночных причин провалилась ниже **85–80% от номинала** при резком всплеске объемов продаж (инсайдеры и поставщики компании узнали о проблемах первыми).

🕵️ 5 КОСВЕННЫХ ПРИЗНАКОВ ДЕФОЛТА (ЗА 1–2 МЕСЯЦА ДО ОБВАЛА)
Как узнать о крахе компании раньше всех:
1. **Блокировка счетов ФНС:** Проверьте ИНН компании на бесплатном сервисе налоговой `service.nalog.ru/bi.do` (раздел «Решения о приостановлении операций по счетам»). Если у компании заблокированы счета за неуплату налогов — купон она не заплатит!
2. **Картотека арбитражных дел (`kad.arbitr.ru`):** Если за последний месяц к компании突然 посыпались десятки исков от поставщиков и банков на крупные суммы — у бизнеса нет живых денег.
3. **Задержка отчета или смена директора за месяц до оферты/погашения.**
4. **Агрессивная реклама нового выпуска облигаций у блогеров** для срочного погашения старого выпуска («пирамида долга»).
5. **Облигации материнской компании или дочерних фирм того же владельца уже допустили технический дефолт.**
''',
