      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Как защитить сбережения от падения курса рубля (девальвации), если хранить наличные доллары под матрасом невыгодно (они не приносят процентов), а покупать иностранные бумаги за рубежом опасно из-за санкций и блокировок?
Решение на Московской бирже — **Замещающие и Юаневые облигации российских гигантов** (Газпром, Лукойл, Новатэк, Совкомфлот, Фосагро, Норникель, Полюс, Металлоинвест).
Как они устроены:
• Номинал облигации выражен в **твердой валюте** — например, **1000 долларов США (USD)**, **1000 Евро (EUR)** или **1000 Юаней (CNY)**.
• Купон тоже начисляется в валюте — например, **7% годовых в долларах ($70 в год)**.
• **ГЛАВНАЯ ФИШКА:** Сама бумага хранится в российском депозитарии (никакие иностранные банки ее заморозить не могут!), а покупка, продажа и выплата всех купонов и номинала происходят **в российских рублях строго по официальному курсу ЦБ РФ на день выплаты**!
Если доллар стоил 90 руб., ваш номинал в рублях стоил 90 000 руб. Если доллар вырос до 110 руб., ваш номинал и купоны автоматически выросли в рублях до 110 000 руб. + валютный процент сверху!

📚 СЛОВАРЬ ТЕРМИНОВ
• Замещающие облигации (ЗО) — российские облигации, выпущенные взамен старых еврооблигаций. Номинал и купон привязаны к USD, EUR, GBP или CHF, а расчеты идут в рублях по курсу ЦБ РФ.
• Юаневые облигации — облигации российских экспортеров, номинированные в китайских юанях (CNY), расчеты по которым идут либо в юанях, либо в рублях по курсу ЦБ.
• Валютная переоценка (налоговый нюанс) — помните, что налог НДФЛ (13%) в России считается **в рублях**! Если вы купили облигацию за $1000 при курсе 85 руб. (85 000 руб.), а погасили за те же $1000 при курсе 105 руб. (105 000 руб.), налоговая посчитает разницу в 20 000 руб. вашей рублевой прибылью и удержит с нее 13% (этого налога можно избежать через ИИС-3 или льготу долгосрочного владения ЛДВ от 3 лет!).

🟢 КОГДА ВХОДИТЬ В ЗАМЕЩАЮЩИЕ И ВАЛЮТНЫЕ ОБЛИГАЦИИ
• **Идеальная точка входа — периоды крепкого рубля!** Когда экспортеры продают много валюты, налоги платятся, а курс доллара/юаня опускается на локальные минимумы и в новостях все говорят «валюта никому не нужна» — планомерно набирайте замещающие или квазивалютные облигации до доли **15–25% вашего портфеля**.
• Раньше порог входа в замещающие облигации был высоким ($1000 ≈ 90–100 тыс. руб. за 1 штуку), но сейчас компании (Фосагро, Новатэк, Полюс, Газпром нефть) выпускают новые валютные облигации с доступным номиналом **$100** или **1000 юаней (~13–14 тыс. руб.)**, а также есть БПИФы на замещающие облигации от 100 рублей.

🔴 КОГДА ВЫХОДИТЬ (ФИКСИРОВАТЬ ВАЛЮТНУЮ ПРИБЫЛЬ)
• Когда случается резкий валютный скачок (девальвация рубля на 20–30% за пару месяцев) и курс валюты взлетает на панике — продавайте часть выросших в рублях замещающих облигаций и перекладывайте прибыль в подешевевшие рублевые ОФЗ или акции!

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если доходность замещающих облигаций в долларах на Мосбирже вдруг поднимается до **9–11% годовых в USD** (за счет падения их цены до 80–85% от номинала) — обычно это вызвано тем, что крупные игроки продают всё подряд, чтобы уйти в рублевые депозиты под 20%. Для долгосрочного инвестора зафиксировать 9–10% годовых в валюте от Газпрома или Лукойла — редкий подарок рынка.
