      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Облигации можно покупать не только в биржевом стакане у других людей (это называется «вторичный рынок»), но и **в самый первый день их рождения напрямую у самой компании-эмитента строго по цене 100% номинала (1000 рублей и с нулевым НКД!)**. Это называется **Первичным размещением**.
В приложении почти каждого брокера есть специальный раздел **«Размещения» (или «Участие в размещении»)**.
Как это происходит:
1. Компания (например, «Атомэнергопром» или «Совкомфлот») объявляет: «Через неделю мы выпускаем новые облигации на 3 года. Ориентир купона: **не выше 19,5% годовых**. Принимаем заявки во вторник с 10:00 до 15:00».
2. Инвесторы и банки подают заявки («книга заявок»).
3. Если спрос огромный (все хотят купить), организаторы **снижают итоговый купон** во время сбора заявок — например, с 19,5% до **18,4% годовых**.
4. Через 2–3 дня облигации зачисляются на ваш счет по 1000 руб. и начинают торговаться в обычном стакане.

📚 СЛОВАРЬ ТЕРМИНОВ
• Первичное размещение (Первичка) — выпуск новых облигаций и продажа их первым покупателям по цене 100% номинала (1000 руб.).
• Букбилдинг (Сбор книги заявок) — день приема заявок от инвесторов, в течение которого определяется финальный размер купона.
• Укатка купона — снижение изначально обещанного ориентира купона во время сбора заявок из-за слишком высокого спроса покупателей.
• Аллокация — процент удовлетворения вашей заявки. Если вы подали заявку на 100 облигаций, а спрос превысил выпуск в 2 раза, вам могут выдать только 50 облигаций (аллокация 50%), а остальные деньги вернутся на счет.
• Апсайд на размещении — быстрый рост цены новой облигации в первые дни торгов в стакане с 100% до 101–102%, если компания оставила щедрый купон.

🟢 КОГДА ВЫГОДНО УЧАСТВОВАТЬ В ПЕРВИЧНОМ РАЗМЕЩЕНИИ
• Выгодно участвовать в размещениях надежных компаний (`A+` / `AA` / `AAA`), когда их **финальный купон оказывается на 0,5% – 1,5% выше**, чем доходность уже торгующихся в стакане старых выпусков этой же компании! В таком случае в первый же день торгов цена новой бумаги в стакане вырастает до 100,8% – 101,5%.
• **Профессиональный прием:** Подавайте заявку в книгу **за 30–40 минут до закрытия сбора заявок (например, в 14:20 при закрытии в 15:00)**! К этому моменту организаторы уже объявляют финальный (сниженный) купон, и вы точно видите, осталась ли бумага выгодной или купон «укатали» слишком низко.

🔴 КОГДА НЕ УЧАСТВОВАТЬ (ОТМЕНЯТЬ ЗАЯВКУ)
• Если во время сбора книги организаторы снизили («укатали») купон так сильно, что в обычном биржевом стакане можно купить старый выпуск этой же компании с такой же или большей доходностью — не участвуйте в размещении! В первый день торгов такая бумага упадет ниже 100% (на 98,5–99%), и купить ее в стакане через день будет дешевле.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ УСПЕШНОГО РАЗМЕЩЕНИЯ
• Если во время сбора заявок компания не только немного снижает купон, но и **увеличивает объем выпуска в 2–3 раза** (например, хотела занять 10 млрд руб., а прямо на ходу увеличила выпуск до 30 млрд руб.) — значит, весь дополнительный объем забирают инвесторы, и большого роста цены выше 100% в первый день торгов ждать не стоит (предложение бумаг полностью насытило спрос).
''',
