      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Никто в мире не знает со 100% точностью, какой будет ключевая ставка ЦБ и инфляция через год. Как составить портфель облигаций так, чтобы вы выигрывали при любом сценарии (и при росте ставки, и при ее падении)?
В мировых финансах для этого используют две проверенные десятилетиями конструкции: **«Лестница»** и **«Штанга»**.

📚 РАЗБОР ДВУХ ГЛАВНЫХ СТРАТЕГИЙ
1. **Стратегия «Лестница облигаций» (Bond Ladder):**
   • Вы делите капитал на равные части (например, на 5 частей по 20%) и покупаете облигации с погашением через равные ступеньки:
     - 1-я ступень: погашение через **6 месяцев**;
     - 2-я ступень: погашение через **1 год**;
     - 3-я ступень: погашение через **1,5 года**;
     - 4-я ступень: погашение через **2 года**;
     - 5-я ступень: погашение через **2,5 года**.
   • Когда через 6 месяцев первая ступень гасится (вам возвращают 1000 руб. номинала), вы перекладываете эти деньги на новую верхнюю ступеньку — на **2,5 года вперед**!
   • **В чем выгода:** Каждые полгода у вас гарантированно освобождаются живые деньги по 100% номинала без всякой просадки. Если ставки выросли — вы вкладываете их под высокий процент. Если ставки упали — остальные 4 длинные ступеньки вашей лестницы продолжают платить вам старый высокий купон!

2. **Стратегия «Штанга» (Barbell Strategy):**
   • Вы не берете средние сроки (2–3 года), а распределяете деньги по двум противоположным краям «штанги»:
     - **Первый блин штанги (50% капитала — сверхнадежная защита и кэш):** Фонды денежного рынка (LQDT) + надежные флоатеры + ультракороткие облигации (до 6 мес.). Эта часть не падает никогда и дает максимальный текущий процент.
     - **Второй блин штанги (50% капитала — максимальный рычаг роста):** Самые длинные 10–15-летние ОФЗ-ПД (серии `26...`), купленные дешево по 50–65% от номинала.
   • **В чем выгода:** Пока ставка ЦБ высокая, первая половина портфеля кормит вас рекордными текущими выплатами. Как только ЦБ намекнет на снижение ставки, вторая половина портфеля (длинные ОФЗ) выстреливает вверх на +25..+40%!

🟢 КОГДА КАКУЮ СТРАТЕГИЮ ПРИМЕНЯТЬ
• **«Лестница»** идеальна, если вам нужна предсказуемость, регулярный доступ к наличным деньгам каждые 3–6 месяцев и защита от угадывания циклов ЦБ.
• **«Штанга»** идеальна в периоды высоких ключевых ставок (16–21%), когда пик ставки уже близко, но точный месяц ее разворота еще неизвестен.

🔴 КОГДА ПЕРЕСТРАИВАТЬ «ШТАНГУ»
• Когда цикл снижения ставки ЦБ уже прошел большую часть пути (например, ставка упала с 20% до 10%), а ваши длинные ОФЗ на втором конце «штанги» уже выросли в цене на 30–35% — продавайте длинный конец штанги, фиксируя сверхприбыль, и переходите в классическую «Лестницу» среднесрочных бумаг.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Построить «Лестницу» можно также для создания **ежемесячной зарплаты из ОФЗ**: поскольку каждая ОФЗ-ПД платит купон 2 раза в год (раз в 6 месяцев), достаточно подобрать всего **6 выпусков ОФЗ** с выплатами в разные месяцы (Январь/Июль, Февраль/Август, Март/Сентябрь, Апрель/Октябрь, Май/Ноябрь, Июнь/Декабрь) — и государственные купоны будут приходить вам на карту каждый месяц года!
''',
      keyRules: [
