      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Куда припарковать свободные рубли на брокерском счете на неделю, месяц или полгода, чтобы они приносили доход на уровне **Ключевой ставки ЦБ**, росли каждый день без единой просадки, и их можно было продать в любую секунду без потери процентов?
Для этого созданы **Биржевые фонды денежного рынка** (самые популярные тикеры на Мосбирже: **LQDT**, **TMON**, **SBMM**, **AKMM**, **BCSD**).
Как устроен такой фонд внутри?
Фонд не покупает рискованные акции или длинные облигации. Каждое утро управляющая компания фонда дает деньги в долг крупнейшим банкам и Центральному контрагенту Мосбиржи **ровно на одни сутки (сделки обратного РЕПО овернайт)** под твердый залог государственных ОФЗ по ставке **RUSFAR** (она почти равна Ключевой ставке ЦБ)!
А на следующее утро фонд забирает деньги с процентами за прошедший день, и цена одного пая фонда в вашем приложении вырастает на `Годовая ставка ЦБ / 365 дней`! График такого фонда выглядит как идеальная прямая линия, идущая вверх под углом 45 градусов каждый день без выходных.

📚 СЛОВАРЬ ТЕРМИНОВ
• Фонд денежного рынка (Money Market Fund) — БПИФ, размещающий деньги в однодневные сделки РЕПО с Центральным контрагентом под ставку, близкую к ключевой ставке ЦБ.
• РЕПО с ЦК (Центральным контрагентом) — сверхнадежная сделка выдачи денег на 1 ночь под залог ценных бумаг, гарантом которой выступает сама Московская биржа (НКЦ).
• RUSFAR (Russian Secured Funding Average Rate) — справедливая стоимость обеспеченных денег на Мосбирже (всегда идет вплотную к ключевой ставке ЦБ РФ).

🟢 КОГДА И КАК ИСПОЛЬЗОВАТЬ ФОНДЫ ДЕНЕЖНОГО РЫНКА (ВХОД)
• **Хранение кэша для будущих покупок:** Никогда не держите свободные рубли на брокерском счете просто так (на них брокер не платит ничего, а крутит их в свою пользу). Всегда паркуйте свободный остаток от 100–1000 рублей в фонд денежного рынка.
• **Выбор конкретного фонда:** Чтобы не терять на комиссиях при коротком хранении (на 1–2 недели), покупайте фонд денежного рынка **своего родного брокера**, за покупку и продажу которого ваш брокер берет **0% комиссии за сделку** (или фонд с самой низкой годовой комиссией УК — например, у LQDT она около 0,3–0,4% в год).

🔴 КОГДА ВЫХОДИТЬ ИЗ ДЕНЕЖНОГО РЫНКА
• Фонд денежного рынка хорош, пока ставка ЦБ высокая. Но у него есть один недостаток перед облигациями: **он не фиксирует ставку на будущее**! Если завтра ЦБ снизит ставку с 18% до 10%, доходность фонда в тот же день упадет до 10%, а его цена не даст никакого дополнительного скачка вверх.
• Поэтому на пике ключевой ставки ЦБ перекладывайте основную часть капитала из фондов денежного рынка в длинные ОФЗ и корпоративные облигации с фиксированным купоном.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ И НАЛОГОВЫЙ ЛАЙФХАК
• В отличие от банковского вклада (где проценты приходят каждый месяц и попадают под налог по итогам года) и облигаций (где с каждого купона сразу списывают 13% налога), фонд денежного рынка **не платит купоны наружу, а капитализирует их внутри цены пая без налога**! Налог возникает только тогда, когда вы сами нажмете кнопку «Продать». А если продержать паи фонда более **3 лет**, то благодаря Льготе долгосрочного владения (ЛДВ) вы вообще законно **освобождаетесь от налога 13%** на доход до 3 млн рублей за каждый год!
''',
