📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Подведем итог Модуля 2. Прежде чем нажать кнопку «Купить» в карточке любой облигации, пробегитесь глазами по этому **60-секундному чек-листу из 7 пунктов**. Он убережет вас от 99% ошибок, на которых теряют деньги частные инвесторы.

📋 ЗОЛОТОЙ ЧЕК-ЛИСТ ПЕРЕД ПОКУПКОЙ ОБЛИГАЦИИ
1. **Кредитный рейтинг (АКРА / Эксперт РА):**
   • Есть ли рейтинг? Он не ниже `A-` / `A` / `AA` / `AAA`? Прогноз «Стабильный» или «Позитивный»? (Если рейтинга нет или он `BB`/`B` с «Негативным» прогнозом — закрываем карточку!).
2. **Проверка на Оферту:**
   • Смотрим строку «Дата оферты» и таблицу всех будущих купонов. Если через полгода стоит Put-оферта, а дальше купоны не назначены — готовы ли вы поставить будильник за 10 дней до оферты, чтобы подать заявку или продать бумагу? Если нет — берем выпуск без оферты!
3. **Проверка на Амортизацию и Текущий номинал:**
   • Равен ли текущий номинал 1000 руб.? Если есть амортизация, цена покупки обязательно должна быть **не выше 100% от номинала**.
4. **Тип купона под текущую фазу ставки ЦБ:**
   • Ставка ЦБ растет или инфляция ускоряется -> берем флоатер (`КС + премия` или `ОФЗ-ПК 29...`) либо короткую бумагу до 1 года.
   • Ставка ЦБ на пике и готовится к снижению -> берем постоянный купон без оферты на 2–10 лет (`ОФЗ-ПД 26...` или корпоративный фикс).
5. **Проверка НКД:**
   • Не покупаем ли мы бумагу за 1–3 дня до выплаты крупного купона с максимальным НКД (чтобы не заморозить 13% налога с чужого НКД)? Лучше подождать пару дней до обнуления НКД или выбрать соседний выпуск, где купон только что выплатили.
6. **Проверка ликвидности и спреда в стакане:**
   • Открываем стакан: разница между лучшим продавцом и лучшим покупателем не должна превышать 0,1% – 0,3%.
7. **Только Лимитная заявка:**
   • Выставляем покупку строго **Лимитной заявкой** по своей четкой цене.

🟢 СИГНАЛ ИДЕАЛЬНОГО ВХОДА
• Все 7 пунктов чек-листа совпали + бумага торгуется по цене **ниже или около 100% номинала**, давая доходность к погашению выше инфляции и выше банковского вклада на тот же срок.

🔴 СИГНАЛ ЭКСТРЕННОГО ВЫХОДА ИЗ УЖЕ КУПЛЕННОЙ ОБЛИГАЦИИ
• Понижение кредитного рейтинга эмитента на 2+ ступени или присвоение статуса «Под наблюдением / Негативный прогноз».
• Пропуск вами окна Put-оферты (лучше продать за неделю до оферты, если новый купон снижен).
• Для длинных бумаг с фиксированным купоном — разворот ЦБ от мягкой политики к новому циклу повышения ключевой ставки.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ ПРОФЕССИОНАЛЬНОГО ОТБОРА
• У одной и той же крупной компании (например, «РЖД», «МТС» или «Газпром нефть») на бирже одновременно торгуется 10–20 разных выпусков облигаций. Из-за неэффективности стакана два абсолютно одинаковых по сроку и надежности выпуска одной компании могут в один день давать разницу в доходности в **1,5% – 2% годовых**! Всегда проверяйте соседние выпуски того же эмитента перед покупкой.
''',
