      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Когда вы покупаете одну обыкновенную акцию Сбербанка за 270 рублей, вы не просто обладатель красивой строчки в телефоне — вы **юридически становитесь совладельцем огромного бизнеса** с сотнями тысяч сотрудников, офисами по всей стране и миллиардными прибылями. Если банк зарабатывает чистую прибыль, часть этих денег совет директоров решает направить на выплату совладельцам (дивиденды), а часть оставляет в компании на развитие (нераспределенная прибыль), что заставляет бизнес расти дальше, а акции — дорожать.

📚 СЛОВАРЬ ТЕРМИНОВ
• Акция (Share) — эмиссионная ценная бумага, закрепляющая право ее владельца на получение части прибыли компании (в виде дивидендов), на участие в управлении и на часть имущества при ликвидации бизнеса.
• Обыкновенная акция — дает право голоса на общем собрании акционеров и право на дивиденды (размер которых меняется от года к году).
• Привилегированная акция («преф») — не дает права голоса на собрании акционеров (или дает в редких случаях), но по закону или уставу гарантирует повышенный или минимально фиксированный дивиденд.
• Эмиссия — выпуск новых акций компанией (размывает долю старых акционеров, если выпускается без необходимости).

🟢 КОГДА ВХОДИТЬ (ПРАВИЛА ИНВЕСТОРА)
• Покупайте акции только тех компаний, чью бизнес-модель вы понимаете (банки продают деньги, ритейлеры продают еду, энергетики продают свет и тепло).
• Заходите в акции частями (стратегия усреднения на просадках), выделяя на один актив не более 5–10% от портфеля акций.

🔴 КОГДА ВЫХОДИТЬ ИЗ БИЗНЕСА НАВСЕГДА
• Если у компании меняется стратегия на ту, которая вам чужда, или руководство замечено в мошенничестве, выводе активов за рубеж через сомнительные «дочки» и перманентном игнорировании миноритариев — немедленно продавайте эту акцию, даже если она в минусе. Спасти оставшиеся деньги важнее надежды на возврат.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Обратите внимание на дивидендную историю: если компания 10–15 лет подряд исправно платит и растит дивиденды даже в кризисы (как Лукойл или Татнефть), это главный показатель надежности менеджмента и уважения к миноритарным акционерам.
''',
