      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
**Дивиденды** — это радость каждого инвестора: компания делит чистую прибыль с акционерами и переводит живые деньги прямо на ваш брокерский счет.
Но новички часто попадают в ловушку «дивидендной отсечки».
Допустим, акция стоит **300 рублей**, и компания объявила дивиденд **30 рублей на одну акцию** (дивидендная доходность 10%). Новичок думает: «Куплю-ка я акцию прямо за день до отсечки, получу свои 30 рублей сверху, а потом продам акцию обратно за 300! Итого +10% чистой прибыли за один день!».
**Это грубейшая ошибка!** В день дивидендной отсечки биржа автоматически уменьшает котировку акции на размер выплачиваемого дивиденда (или около того). Акция открывается в 10:00 утра не по 300, а по **270 рублей**. Это падение цены называется **Дивидендным гэпом (разрывом)**. Вы получили 30 рублей дивидендов на счет, но цена самой акции в портфеле упала на 30 рублей. Суммарно ваш капитал в эту секунду не изменился!

📚 СЛОВАРЬ ТЕРМИНОВ
• Дивидендная отсечка (Record Date) — дата, по состоянию на которую составляется список акционеров, имеющих право на получение дивидендов. Чтобы попасть в список, нужно купить акцию минимум за 1 рабочий день до отсечки (в режиме Т+1).
• Дивидендный гэп (Dividend Gap) — падение цены акции на бирже в первый день торгов без дивидендов (обычно на величину дивиденда за вычетом налога).
• Закрытие гэпа — возвращение цены акции к уровню до отсечки (может занять от нескольких дней до нескольких месяцев).

🟢 КОГДА ВХОДИТЬ ПОД ДИВИДЕНДЫ (СТРАТЕГИЯ)
• Самый надежный способ заработать на дивидендах — покупать акцию **за несколько месяцев ДО отсечки**, когда рынок еще только ожидает рекордной выплаты и цена плавно растет.
• Покупать акцию за 1–2 дня до отсечки ради «быстрых дивидендов» статистически невыгодно: вам придется заплатить налог 13% с дивидендов сразу, а сам дивидендный гэп может восстанавливаться несколько месяцев.

🔴 КОГДА ВЫХОДИТЬ
• Если акция перед отсечкой на ожиданиях дивидендов выросла слишком сильно (например, на +40% за два месяца), а сам дивиденд составляет всего 8% — часто выгоднее продать акцию ДО отсечки, забрав этот рост целиком, и не ждать дивидендного гэпа и заморозки денег.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Компании с сильным бизнесом (Сбер, Лукойл, Транснефть) закрывают дивидендный гэп быстро (за 2–4 недели), так как их прибыль продолжает расти. У слабых компаний дивидендный гэп может не закрываться годами («вечный гэп»).
''',
