      id: 33,
      moduleId: 3,
      moduleTitle: 'Модуль 3. Акции и Дивиденды',
      title: 'Урок 33. Фундаментальный анализ: Мультипликатор P/E (Цена / Прибыль)',
      category: 'Анализ акций',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Как понять, стоит ли акция компании своих денег или она безумно переоценена («пузырь»)?
Представьте, что вы покупаете не акцию, а небольшой ларек с шаурмой за **1 000 000 рублей**. Вы заглядываете в его бухгалтерию и видите, что чистая прибыль ларька составляет **200 000 рублей в год**.
За сколько лет окупится ваш ларек? `1 000 000 / 200 000 = 5 лет`.
В мире акций этот показатель называется **P/E (Price to Earnings — Цена / Прибыль)**. В нашем примере P/E равен **5**.
• Если P/E равен **5** — бизнес окупается за 5 лет (это дешево и выгодно).
• Если P/E равен **35** — бизнес окупится только через 35 лет (компания стоит очень дорого, инвесторы закладывают огромные надежды на будущее).
• Если P/E отрицательный — компания работает **в убыток**!

📚 СЛОВАРЬ ТЕРМИНОВ
• P/E (Price / Earnings) — отношение рыночной капитализации компании к ее годовой чистой прибыли (или цены одной акции к прибыли на одну акцию — EPS).
• Исторический P/E — средний мультипликатор компании за последние 5–10 лет. Позволяет понять, дорога ли акция сама по себе сегодня.
• Отраслевой P/E — сравнение мультипликатора компании с ее конкурентами по сектору (например, сравнивать Сбер и Т-Банк, Лукойл и Роснефть).

🟢 КОГДА ВХОДИТЬ ПО P/E
• Ищите компании, у которых P/E **ниже исторического среднего для этой отрасли** и ниже рынка в целом (например, P/E < 6–8 для российских сырьевых и финансовых гигантов при стабильной экономике).
• Низкий P/E — отличный сигнал для входа, но только при условии, что чистая прибыль компании не является разовой (например, от продажи завода год назад).

🔴 КОГДА ВЫХОДИТЬ
• Если P/E компании взлетел в 3–5 раз выше нормы (например, до 30–40 при исторических 8) без взрывного роста выручки — это спекулятивный «пузырь». Пора фиксировать прибыль.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ ЛОВУШКИ НИЗКОГО P/E
• Иногда у компании фантастически низкий P/E (например, 2 или 3), но покупать ее нельзя! Почему? Потому что в этом году компания продала свой главный актив (завод или нефтяное месторождение), показала гигантскую **разовую** бумажную прибыль, а на следующий год ее прибыль упадет до нуля. Всегда смотрите на *структуру* прибыли, а не только на цифру P/E.
''',
      keyRules: [
        'P/E (Цена / Прибыль) показывает, за сколько лет окупится покупка бизнеса при текущей чистой прибыли.',
        'Сравнивайте P/E только внутри одной отрасли (нельзя сравнивать IT-компанию с банком или металлургом).',
        'Аномально низкий P/E часто бывает «бумажным» из-за разовой продажи активов в отчете за прошлый квартал.'
      ],
      question: 'Компания имеет капитализацию 10 миллиардов рублей, а ее чистая прибыль за последний год составила 2 миллиарда рублей. Чему равен коэффициент P/E?',
      options: [
        'P/E = 0,2',
        'P/E = 5 (10 млрд делим на 2 млрд, бизнес окупается за 5 лет)',
        'P/E = 20',
        'P/E = 10 миллиардов'
      ],
      correctOptionIndex: 1,
      explanation: 'Коэффициент P/E рассчитывается как деление общей капитализации на чистую прибыль (или цены акции на прибыль на акцию): 10 / 2 = 5.'
    ),

    Lesson(
      id: 34,
      moduleId: 3,
      moduleTitle: 'Модуль 3. Акции и Дивиденды',
      title: 'Урок 34. Мультипликаторы EV/EBITDA и Долг / EBITDA: как найти компанию-банкрот',
      category: 'Анализ акций',
      readingTimeMinutes: 8,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Одного мультипликатора P/E мало, потому что он не учитывает **долги компании**.
Представьте две одинаковые компании с одинаковой прибылью:
• Компания «А» зарабатывает чистую прибыль и **не имеет кредитов**.
• Компания «Б» зарабатывает ту же чистую прибыль, но висит на **огромных кредитах** в банках под 20% годовых.
Если ставка ЦБ вырастет, компанию «Б» разорвет от процентных платежей, а компания «А» останется здоровой.
Чтобы учесть долги, профессионалы используют связку **EV/EBITDA** и **Net Debt / EBITDA**.

📚 СЛОВАРЬ ТЕРМИНОВ
• EBITDA — операционная прибыль компании **до** вычета налогов, процентов по кредитам и амортизации оборудования. Это чистая «сила мотора» бизнеса до всех финансовых долгов.
• EV (Enterprise Value, Стоимость бизнеса) — реальная цена всей компании с учетом всех ее долгов минус живые деньги на счетах (`Капитализация + Долги - Кэш`).
• EV/EBITDA — улучшенный аналог P/E, показывающий окупаемость всего бизнеса с учетом долгов. Норма для стабильного рынка: от 3 до 7.
• **Net Debt / EBITDA (Чистый долг / EBITDA) — главный индикатор опасности банкротства!**
  - Меньше 1,0 — долгов почти нет, компания железобетонно надежна.
  - От 1,0 до 2,0 — нормальная умеренная нагрузка.
  - **Выше 3,0 — красный уровень опасности!** При высокой ключевой ставке ЦБ такой бизнес начинает отдавать всю прибыль банкам и может объявить дефолт.

🟢 КОГДА ВХОДИТЬ
• Ищите компании с **Net Debt / EBITDA ниже 1,5** и EV/EBITDA ниже исторических средних по сектору. Это финансово здоровые лидеры.

🔴 КОГДА УБЕГАТЬ (ПРАВИЛО СЕГЕЖИ И МЕЧЕЛА)
• Если Net Debt / EBITDA компании вырастает **выше 3,5 – 4,0** на фоне роста ставок ЦБ или падения цен на ее продукцию — немедленно продавайте акции этой компании. Спасать ее будут за счет дополнительной эмиссии акций (размывания вашей доли в 2–3 раза) или реструктуризации долгов с убытками для миноритариев.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если менеджмент компании начинает публично уверять в интервью: «Наш высокий долг — это нормально, мы инвестируем в будущее», но при этом ключевая ставка растет, а операционный денежный поток падает — это классическая мантра обреченного топ-менеджмента перед допэмиссией или кризисом.
''',
      keyRules: [
