      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Каждые 3 месяца (квартал) и раз в год (годовой отчет) публичные компании обязаны раскрывать свои финансовые результаты. Новичок пугается сложных таблиц, но вам нужно знать всего **3 главные строки** в любом финансовом отчете:
1. **Выручка (Revenue):** Сколько всего денег принесли клиенты за продажу товаров или услуг (верхняя строка отчета). Выручка должна расти из года в год.
2. **Операционная прибыль / EBITDA:** Сколько денег осталось у компании после оплаты сырья, зарплат, аренды и логистики (до вычета налогов и кредитов).
3. **Чистая прибыль (Net Income):** Финальный остаток денег после выплаты всех налогов, кредитов и амортизации. Именно из чистой прибыли платятся дивиденды!

📚 СЛОВАРЬ ТЕРМИНОВ
• МСФО (Международные стандарты финансовой отчетности) — консолидированный отчет всей группы компаний целиком (включая все зарубежные «дочки», заводы и логистику). **Для инвестора существует только МСФО!**
• РСБУ (Российские стандарты бухгалтерского учета) — отчет только юридического лица в России. РСБУ часто искажает реальную картину (например, Сбер отчитывается по РСБУ отлично, но для других компаний РСБУ — лишь черновик).
• Рентабельность по чистой прибыли (Net Profit Margin) — отношение чистой прибыли к выручке в процентах. Показывает, сколько копеек чистой прибыли остается с каждого рубля продаж.

🟢 КОГДА ВХОДИТЬ (СИГНАЛЫ СИЛЬНОГО ОТЧЕТА)
• Покупайте акции компании в день выхода отчета МСФО, если выполняются три условия:
  1. Выручка выросла по сравнению с тем же кварталом прошлого года (г/г) на 15% и более.
  2. Чистая прибыль выросла быстрее выручки (компания умеет контролировать расходы).
  3. Долговая нагрузка (Net Debt / EBITDA) снизилась или осталась низкой.

🔴 КОГДА ВЫХОДИТЬ (ПРИЗНАКИ СЛАБОСТИ)
• Если в отчете МСФО выручка растет, но **чистая прибыль падает в ноль или уходит в минус** из-за резкого роста коммерческих расходов или убытков по курсовым разницам — это тревожный сигнал. Крупные фонды начнут распродавать такие акции.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ И ОБМАН В ОТЧЕТАХ
• Всегда проверяйте строку **«Операционный денежный поток» (Cash Flow from Operating Activities)** в отчете о движении денежных средств. Чистая прибыль может быть нарисована бухгалтером на бумаге за счет переоценки активов, но если операционный денежный поток отрицательный (живых денег от клиентов на счета не поступило) — у компании серьезные проблемы с собираемостью платежей!
''',
