      category: 'Акции',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Что делает успешная компания, когда у нее на счетах накопилось много свободных денег, а новые заводы строить не нужно? Она может выплатить их дивидендами, а может объявить **Buyback (Обратный выкуп акций)**.
Компания выходит на биржу и начинает сама на свои деньги скупать свои же акции у инвесторов, после чего погашает (уничтожает) их.
Как это влияет на ваш кошелек:
• До байбека у компании было всего 100 акций на рынке, и ваша 1 акция составляла **1%** от всего бизнеса.
• Компания выкупила и уничтожила 10 акций. Теперь на рынке осталось всего 90 акций.
• Ваша 1 акция теперь составляет уже `1 / 90 = 1,11%` от бизнеса!
• Поскольку доля каждого акционера в оставшейся прибыли выросла, **цена оставшихся акций автоматически идет вверх**.

📚 СЛОВАРЬ ТЕРМИНОВ
• Buyback (Байбек) — программа обратного выкупа компанией собственных акций с открытого рынка.
• Погашение акций — аннулирование выкупленных акций (уменьшение общего количества бумаг в обращении).
• Квази-байбек — выкуп акций на баланс «дочерних» структур компании (акции не уничтожаются полностью, но изымаются из свободного обращения).

🟢 КОГДА БАЙБЕК — СИГНАЛ К ПОКУПКЕ
• Если совет директоров объявляет байбек **с реальным погашением акций** и заявляет: «Мы будем скупать бумаги с рынка, так как считаем их сильно недооцененными» — это мощнейший сигнал силы бизнеса и защиты миноритариев (так делает, например, Лукойл).

🔴 КОГДА БАЙБЕК НЕ РАБОТАЕТ (ЛОВУШКА)
• Если компания скупает акции не для погашения, а чтобы потом раздать их топ-менеджерам в виде бонусов (мотивационная программа), общее количество акций на рынке не уменьшается, и для миноритариев это бесполезно или даже вредно.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если компания объявляет байбек, но параллельно выпускает новые акции в рамках допэмиссии для покупки какого-то сомнительного непрофильного актива — это манипуляция, от таких историй лучше держаться подальше.
''',
      keyRules: [
