      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Все акции на бирже делятся по отраслям («секторам»), и каждый сектор ведет себя по-своему в зависимости от фазы экономической погоды:
1. **Защитные сектора (Ритейл, Телеком, Электроэнергетика):** Продукты питания, связь и свет нужны людям всегда, даже во время глубокого кризиса. Выручка X5 Group, Магнита или МТС стабильна в любую погоду.
2. **Циклические сектора (Металлурги, Нефтегаз, Химия, Уголь, Застройщики):** Их доходы полностью зависят от мировых цен на сырье и курса доллара. Когда в мире бум и стройка — Северсталь, НЛМК и ММК зарабатывают фантастические миллиарды. Когда в мире рецессия и падает спрос — их прибыль и дивиденды сжимаются в 3–5 раз.

📚 СЛОВАРЬ ТЕРМИНОВ
• Циклические компании — бизнес, чьи финансовые результаты жестко колеблются вслед за экономическими циклами (металлы, нефть, уголь, девелопмент).
• Защитные компании (Consumer Staples / Utilities) — стабильный бизнес с предсезонным спросом, устойчивый к кризисам (продуктовые супермаркеты, коммунальные сети).
• Санкционное давление — фактор дисконта для российских экспортеров сырья, меняющий логистику поставок в Азию.

🟢 СТРАТЕГИЯ ВХОДА ПО ЦИКЛАМ
• **В начале кризиса и при высоких ставках ЦБ:** Увеличивайте долю защитных секторов (ритейл, внутренние монополии) и сокращайте циклические сырьевые компании с долгами.
• **В момент выхода экономики из кризиса и ослабления рубля:** Первыми скупайте акции циклических экспортеров (нефтегаз и металлурги), пока они стоят дешево на донных отчетах.

🔴 ОШИБКИ НОВИЧКОВ
• Покупать акции металлургов на пике мировых цен на сталь в расчете на «вечные дивиденды 20%» — именно в этот момент цикл разворачивается вниз, дивиденды отменяются, а акции падают на 40–50%.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ РАЗВОРОТА ЦИКЛА
• Если мировые цены на сталь или нефть падают 3 месяца подряд, а аналитики в СМИ продолжают писать, что «это временная коррекция» — цикл уже сменился вниз, пора выходить из циклических историй.
''',
