      moduleTitle: 'Модуль 3. Акции и Дивиденды',
      title: 'Урок 38. Скрытые ловушки миноритариев: допэмиссия, квази-суверенные риски и юрисдикция',
      category: 'Риски акций',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Быть миноритарием (владельцем крошечной доли компании) на российском рынке — значит помнить о защите своих интересов. Иногда мажоритарные акционеры (крупные владельцы или государство) принимают решения, которые грабят миноритариев, даже не нарушая формально законов.

📚 СЛОВАРЬ ТЕРМИНОВ
• Миноритарный акционер — инвестор, владеющий небольшой долей акций компании (не позволяющей напрямую влиять на решения совета директоров).
• Дополнительная эмиссия (Допэмиссия) — выпуск новых акций компанией. Если новые акции распределяются в пользу одного крупного владельца за копейки, доля всех старых миноритариев «размывается» в несколько раз.
• Редомициляция — переезд компании из иностранной юрисдикции (Кипр, ОАЭ, Джерси) в российскую специальную зону (острова Октябрьский во Владивостоке или Русский в Калининграде). После завершения переезда и возобновления торгов компании снова получают право платить дивиденды (как это сделали Etalon, Globaltrans, Ozon, HeadHunter).

🟢 КАК ЗАЩИТИТЬ СЕБЯ ПРИ ВХОДЕ
• Избегайте компаний, которые исторически замечены в скандалах с допэмиссиями или невыплатой дивидендов при наличии прибыли.
• Внимательно следите за новостями о редомициляции: компании в процессе переезда часто временно останавливают торги на 1–3 месяца.

🔴 КОГДА ВЫХОДИТЬ
• Если компания объявляет о реструктуризации бизнеса с обменом акций старой зарубежной головной компании на бумаги новой российской структуры по невыгодному для миноритариев коэффициенту — это красный флаг.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
