      title: 'Урок 39. Использование ИИС-3 и налоговых льгот (ЛДВ): как не платить 13% государству',
      category: 'Налоги и льготы',
      readingTimeMinutes: 8,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Зачем отдавать государству 13% (или 15% для доходов выше 2,4 млн руб.) с вашей честно заработанной прибыли на бирже, если государство само создало законные инструменты, чтобы освободить вас от налогов?
В России с 2024 года действует единый инструмент — **ИИС-3 (Индивидуальный инвестиционный счет третьего типа)**, а также старая добрая **Льгота долгосрочного владения (ЛДВ)** для обычных брокерских счетов.

📚 СЛОВАРЬ ТЕРМИНОВ
• ИИС-3 — специальный брокерский счет нового поколения. Дает сразу **две налоговые льготы**:
  1. Вычет на взносы (возврат до 52 000 – 60 000 рублей живыми деньгами от налоговой каждый год с внесенных до 400 тыс. руб.).
  2. Полное освобождение от налога 13% всей инвестиционной прибыли при закрытии счета (на сумму до 30 млн рублей!).
• Минимальный срок ИИС-3 для получения льгот: в переходный период он составляет 5 лет (с постепенным ростом до 10 лет в зависимости от года открытия).
• ЛДВ (Льгота долгосрочного владения) — освобождение от налога 13% прибыли при продаже акций или облигаций на **обычном брокерском счете**, если вы продержали конкретную ценную бумагу **более 3 лет** (лимит необлагаемой прибыли — до 3 млн рублей за каждый год владения).

🟢 КАК ПРИМЕНЯТЬ ДЛЯ МАКСИМАЛЬНОЙ ВЫГОДЫ
• Откройте ИИС-3 у своего брокера (на один человек может быть открыто до трех ИИС-3 одновременно) и ежегодно пополняйте его сумму до 400 000 рублей, чтобы оформлять ежегодный возврат НДФЛ через налоговую (Госуслуги / Налог.ру).
• На обычном брокерском счете держите акции и замещающие облигации, которые планируете не продавать более 3 лет, чтобы задействовать ЛДВ.

🔴 ЧЕГО ДЕЛАТЬ НЕЛЬЗЯ
• Закрывать ИИС-3 раньше положенного минимального срока (иначе придется не только вернуть государству все ранее полученные вычеты, но и заплатить пени).
• Путать ИИС старого типа (ИИС-1 и ИИС-2, которые открывались до 2024 года) с новым ИИС-3.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Обратите внимание: дивиденды по акциям на ИИС-3 по закону приходят за вычетом налога 13% сразу (их удерживает эмитент при выплате), но налог с прироста тела акций при продаже счета через 5 лет вы полностью обнулите!
''',
