      category: 'Практика',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Дивидендная стратегия — самая популярная среди частных инвесторов в России, так как российский рынок исторически обладает одной из самых высоких дивидендных доходностей в мире (в среднем 8–12% годовых в дивидендах против 1–2% в США).
Но погоня за «самыми жирными дивидендами» губит новичков. Разберем **топ-5 смертельных ошибок дивидендного инвестора**:

❌ ТОП-5 ОШИБОК ДИВИДЕНДНОГО ИНВЕСТОРА:
1. **Погоня за дивидендной доходностью в моменте (Yield Trap):** Видеть акцию с дивидендом 25% и покупать ее, не глядя на отчетность. В 99% случаев это «дивидендная ловушка»: компания распродала последние активы, показала разовую прибыль, а на следующий год дивидендов не будет, а акция рухнет на 50%.
2. **Покупка акций под дивиденды на заемные средства («с плечом»):** Занимать у брокера или брать кредит под покупку акций перед отсечкой. Дивидендный гэп вниз уничтожит ваш заемный капитал, и маржин-колл принудительно закроет сделку с огромным убытком.
3. **Отсутствие диверсификации по секторам:** Собрать портфель из 8 металлургов или 6 банков. При кризисе в одной отрасли падает весь портфель.
4. **Игнорирование налогов:** Забывать, что с любых дивидендов брокер автоматически удерживает 13% (или 15% свыше 2,4 млн руб. дохода), поэтому реальный денежный поток на руки будет чуть ниже расчетного.
5. **Отказ от реинвестирования:** Тратить дивиденды на сиюминутные радости вместо покупки новых акций в первые 3–5 лет формирования капитала.

🟢 ПРАВИЛЬНЫЙ АЛГОРИТМ СБОРКИ ДИВЕНДНОГО ПОРТФЕЛЯ
• Выбирайте компании с историей непрерывных выплат от 5–10 лет.
• Убедитесь, что коэффициент выплаты дивидендов (Payout Ratio) находится на здоровом уровне (от 50% до 80% от чистой прибыли по МСФО, а не 150%, когда компания платит дивиденды в долг).
• Диверсифицируйте портфель по 5–6 несвязанным секторам (нефтегаз, банки, ритейл, энергетика, IT/телеком).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если компания официально заявляет в дивидендной политике: «Мы направляем на дивиденды не менее 50% от чистой прибыли по МСФО при условии, что Net Debt / EBITDA ниже 2.0» — это прозрачная и предсказуемая история, за которую инвесторы готовы платить высокую цену акций.
''',
