      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
У многих крупных российских компаний на бирже торгуется сразу два вида акций: **обыкновенные** и **привилегированные (префы)**. Например, Сбер (`SBER` и `SBERP`), Сургутнефтегаз (`SNGS` и `SNGSP`), Мечел (`MTLR` и `MTLRP`), Транснефть (`TRNF` — только префы).
В чем разница для инвестора?
• **Обычка** дает право голоса на собрании акционеров.
• **Преф** права голоса обычно не дает, но по уставу компании на него **гарантированно выплачивается фиксированный или повышенный дивиденд** (например, не менее 10% чистой прибыли, разделенной на число префов).

📚 СЛОВАРЬ ТЕРМИНОВ
• Дивидендная доходность префов — часто оказывается выше, чем у обычки, потому что префы на бирже стоят дешевле (так как у них нет права голоса, крупные фонды с миллиардами голосов голосуют обычкой, а частным инвесторам голос не нужен, им важны деньги).
• «Кубышка» Сургутнефтегаза — легендарный пример, где префы Сургутнефтегаза исторически платят огромные дивиденды при ослаблении рубля (по уставу на префы направляется строго 10% чистой прибыли по РСБУ, включая валютную переоценку кубышки).

🟢 КОГДА ВЫБИРАТЬ ПРЕФЫ
• Если компания честно платит дивиденды и прописала в уставе четкую формулу для привилегированных акций (как Сбер или Сургутнефтегаз), **покупайте префы (`-p`)**: они стоят дешевле обычки, а дивиденды приносят такие же или даже выше!

🔴 КОГДА ПРЕФЫ ОПАСНЫ
• Если у компании тяжелые времена, а в уставе написано, что дивиденды по префам выплачиваются «если на это будет решение совета директоров» (без жесткой формулы процента от прибыли), то в кризис вы не получите ничего, как и владельцы обычки, но потеряете право голоса.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Обратите внимание на спред между обычкой и префами: если исторически преф стоил на 10–15% дешевле обычки, но дает точно такие же дивиденды, покупка префа приносит инвестору дополнительную дивидендную доходность на вложенный рубль.
''',
      keyRules: [
        'Привилегированные акции («префы») часто торгуются с дисконтом к обыкновенным акциям при аналогичных или более высоких дивидендах.',
