      category: 'Анализ рынка',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
**Индекс Мосбиржи (IMOEX)** — главный барометр российского рынка акций. Это корзина из примерно 40–45 ведущих публичных компаний страны, вес каждой из которых в индексе зависит от ее размера (капитализации) и количества свободных акций в обращении (free-float).
Главная особенность индекса Мосбиржи — его **колоссальная концентрация в сырьевых и финансовых гигантах**:
• Сбербанк, Лукойл, Газпром, Роснефть, Норникель, Новатэк и ТКС Холдинг суммарно занимают **более 65–70% всего индекса**!
Это значит, что когда растет Сбер и Лукойл — растет весь российский рынок акций. Когда они падают — падает весь индекс.

📚 СЛОВАРЬ ТЕРМИНОВ
• Free-float (Фри-флоат) — доля акций компании, которая находится в свободном обращении у миноритарных инвесторов на бирже (а не заперта у государства или ключевых мажоритариев). Чем выше фри-флоат, тем выше вес компании в индексе IMOEX.
• БПИФ на индекс Мосбиржи (фонды вроде SBMX, EQMX, AMRE) — готовый инструмент, покупая который вы за 100–150 рублей приобретаете крошечные кусочки всех 40+ компаний индекса разом.

🟢 КОГДА ПОКУПАТЬ ИНДЕКСНЫЕ ФОНДЫ
• Для инвесторов, у которых нет времени изучать квартальные отчеты МСФО каждой компании по отдельности, покупка широкого фонда на индекс Мосбиржи регулярными равными частями (стратегия DCA — усреднение долларовой стоимости) — **лучшая пассивная стратегия на горизонте от 3–5 лет**.

🔴 ОШИБКИ ИНДЕКСНОГО ИНВЕСТОРА
• Думать, что индекс Мосбиржи защищен от всех рисков. Поскольку сырье и банки занимают в нем 80%, индекс сильно проседает при падении цен на нефть или санкциях против финансового сектора.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Обратите внимание на индекс полной доходности **MCFTR** (Мосбиржа с учетом дивидендов): долгосрочно график MCFTR уходит значительно выше обычного IMOEX, потому что гигантские российские дивиденды реинвестируются внутри индекса.
''',
      keyRules: [
        'Индекс Мосбиржи (IMOEX) на 70% состоит из тяжеловесов финансового и сырьевого секторов (Сбер, Лукойл, Газпром и др.).',
        'Покупка БПИФ на индекс Мосбиржи — простейший способ мгновенной диверсификации по всему российскому рынку акций.',
        'Индекс полной доходности MCFTR учитывает реинвестирование дивидендов и на длинной дистанции всегда обгоняет чистый индекс IMOEX.'
      ],
      question: 'Вы хотите купить биржевой фонд (БПИФ) на весь российский рынок акций, чтобы не выбирать отдельные компании вручную. Какой главный сектор будет доминировать в таком фонде?',
      options: [
