📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Сколько процентов денег держать в рискованных акциях, а сколько — в надежных облигациях и денежном рынке?
В мировой финансовой практике есть классическое эмпирическое правило для определения баланса портфеля: **«100 минус ваш возраст»**.
• Если вам **30 лет**, то доля акций в вашем портфеле может составлять `100 - 30 = 70%` (остальные 30% — облигации и кэш). У вас длинный горизонт впереди, вы можете спокойно пересидеть любые кризисы и падения рынка.
• Если вам **60 лет**, доля акций должна быть не выше `100 - 60 = 40%` (а лучше 30%), так как вам важнее стабильный денежный поток и сохранность капитала без глубоких просадок.

📚 СЛОВАРЬ ТЕРМИНОВ
• Аллокация активов (Asset Allocation) — распределение капитала между классами активов (акции, облигации, денежный рынок, золото, недвижимость).
• Профиль инвестора — степень готовности рисковать ради доходности.

🟢 КАК ПРИМЕНЯТЬ ПРАВИЛО АЛЛОКАЦИИ
• Не копируйте слепо чужие портфели («всё в акции роста» или «всё в защитные облигации»). Ваша пропорция зависит от трех китов:
  1. **Ваш возраст** и стабильность личного дохода.
  2. **Ваш горизонт инвестирования** (когда понадобятся деньги).
  3. **Ваш психологический темперамент** (можете ли вы спать спокойно, если ваш портфель временно упал на 20%).

🔴 ОШИБКИ АЛЛОКАЦИИ
