📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Подведем итог Модуля 3. Перед тем как нажать кнопку «Купить» в приложении брокера для приобретения любой акции или дивидендного портфеля, пройдите этот финальный **7-шаговый чек-лист**.

📋 7 ШАГОВ ЧЕК-ЛИСТА АКЦИОНЕРА:
1. **Понимаю ли я бизнес?** (Продает ли компания понятный товар или услугу, растет ли ее выручка?).
2. **Какова долговая нагрузка?** (Net Debt / EBITDA строго ниже 2,0–2,5, компания не задохнется при высоких ставках ЦБ?).
3. **Что с оценкой по P/E и EV/EBITDA?** (Не переплачиваем ли мы за бизнес в 3 раза дороже его исторических средних значений?).
4. **Какова дивидендная история?** (Платит ли компания дивиденды регулярно, есть ли прозрачная дивидендная политика, не является ли высокая доходность «дивидендной ловушкой»?).
5. **Есть ли инфраструктурная безопасность?** (Торгуется ли бумага в российском контуре без риска блокировки депозитария?).
6. **Соответствует ли сделка моему риск-профилю и аллокации?** (Не превышает ли доля этой компании 5–10% вашего портфеля акций?).
7. **Использую ли я лимитную заявку и льготу?** (Покупаем ли мы через лимитный ордер по честной цене, оформлен ли ИИС-3 или учтена ли льгота ЛДВ?).

🟢 СИГНАЛ ИДЕАЛЬНОЙ ПОКУПКИ
• Все 7 пунктов чек-листа совпали, отчет МСФО за последний квартал сильный, долговая нагрузка низкая, а цена бумаги на рынке просела на фоне общего страха толпы («покупай, когда льется кровь»).

🔴 СИГНАЛ К ЭКСТРЕННОЙ ПРОДАЖЕ АКЦИИ
• Ухудшение операционных показателей в двух отчетах МСФО подряд, рост долгов выше критических уровней, отказ от дивидендов на фоне ухудшения бизнеса или угроза токсичной допэмиссии.

