📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Золото — классический защитный актив на случай войн, геополитических кризисов и обесценивания бумажных валют. Но покупать физические слитки в банке неудобно (нужно платить НДС при покупке, хранить в сейфе, а при продаже банк занижает цену).
На бирже есть три цивилизованных способа владения золотом:
1. **БПИФ на золото (тикеры: GOLD, TGLD, RUGL):** Фонд покупает реальное физическое золото в хранилищах и хранит его. Вы покупаете пай фонда за рубли в приложении брокера. Удобно, ликвидно, комиссия копеечная.
2. **ОМС (Обезличенный металлический счет):** Виртуальный счет в банке в граммах золота. Минус: счета по ОМС **не застрахованы АСВ** (на сумму до 1,4 млн руб.), и банк устанавливает невыгодный спред на покупку/продажу.
3. **Физическое золото в слитках:** Без НДС (с 2022 года в РФ отменили НДС на покупку слитков), но требует безопасного хранения.

📚 СЛОВАРЬ ТЕРМИНОВ
• Драгоценный металл (аурум) — защитный актив с обратной корреляцией к падающим валютам.
• Спред по золоту — разница между ценой покупки и продажи металла банком или биржей.

🟢 КОГДА ПОКУПАТЬ ЗОЛОТО
• Держите в золоте **5–15% вашего портфеля** в качестве вечной страховки от девальвации и глобальных кризисов.
• Покупайте золото в периоды стабильности и крепкого рубля, когда котировки драгметалла на мировых рынках временно проседают.

🔴 КОГДА НЕ СТОИТ ЖДАТЬ ЧУДЕС
• Золото не платит дивидендов и купонов! Его доходность зависит исключительно от роста мировой цены за унцию и изменения курса доллара к рублю.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Когда центробанки разных стран мира начинают массово скупать физическое золото в свои резервы — это сильный фундаментальный сигнал долгосрочного роста цен на металл.
''',
