      category: 'Технический анализ',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Технический анализ — это изучение графиков цен и объемов торгов с целью предсказать будущее движение цены. В отличие от фундаментального анализа (который смотрит на балансы и прибыль), технарëк считает, что **вся информация о компании уже мгновенно заложена в ее текущей цене**. Главная философия: «История повторяется, потому что человеческая психология (страх и жадность) не меняется веками».

📚 СЛОВАРЬ ТЕРМИНОВ
• Тренд (Trend) — направление движения цены. Бывает восходящим (бычьим), нисходящим (медвежьим) и боковым (флэт).
• Уровень поддержки (Support) — ценовая зона, где покупателей так много, что цена останавливается и отскакивает вверх (как от пола).
• Уровень сопротивления (Resistance) — ценовая зона, где продавцов так много, что цена ударяется о нее и разворачивается вниз (как о потолок).

🟢 КАК ИСПОЛЬЗОВАТЬ
• Никогда не торгуйте против сильного глобального тренда на дневном графике (Daily). Покупайте на восходящем тренде у уровней поддержки.

🔴 ОШИБКИ
• Чертить бесконечное количество линий на графике до тех пор, пока они не перестанут иметь хоть какой-то смысл.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Если цена трижды за месяц ударилась об один и тот же уровень сопротивления и не смогла его пробить — этот «потолок» очень сильный, пробить его с первой попытки вряд ли удастся.
''',
