      title: 'Урок 52. Скользящие средние (SMA и EMA): определяем тренд за 5 секунд',
      category: 'Индикаторы',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Скользящая средняя (Moving Average) — самый популярный и простой технический индикатор. Он сглаживает случайные колебания цены и рисует плавную линию среднего значения цены за выбранный период.
• **SMA (Simple Moving Average):** Простое среднее арифметическое цен за N дней.
• **EMA (Exponential Moving Average):** Экспоненциальное среднее, которое дает больший вес последним дням, быстрее реагируя на смену тренда.

📚 СЛОВАРЬ ТЕРМИНОВ
• «Золотой крест» — классический бычий сигнал: быстрая скользящая средняя (например, SMA 50) пересекает медленную скользящую среднюю (SMA 200) снизу вверх. Это предвестник долгого роста.
• «Крест смерти» — медвежий сигнал: быстрая SMA пересекает медленную SMA сверху вниз, сигнализируя о начале долгого падения.

🟢 КАК ИСПОЛЬЗОВАТЬ
• На ежедневном графике (Daily) используйте классические связки EMA 50 и EMA 200 для определения глобального тренда.

🔴 ОШИБКИ
• Слепо доверять пересечениям скользящих в боковом рынке (флэте), когда они дают множество ложных сигналов («пилится» депозит).

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Когда цена акции уверенно держится выше своей растущей EMA 200 — на рынке сильный глобальный бычий тренд.
''',
