      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
**RSI (Relative Strength Index)** измеряет скорость и масштаб изменения цен, чтобы показать, когда актив перегрет покупателями («перекуплен») или задавлен продавцами («перепродан»). RSI колеблется от 0 до 100 в отдельном окне под графиком.
• Зона **выше 70** — рынок перекуплен (покупатели истощены, высок риск коррекции).
• Зона **ниже 30** — рынок перепродан (продавцы истощены, актив может отскочить вверх).

📚 СЛОВАРЬ ТЕРМИНОВ
• Дивергенция RSI — мощнейший разворотный паттерн: цена обновляет максимумы, а пики индикатора RSI при этом падают. Это скрытый сигнал скорого обвала.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Используйте RSI как вспомогательный фильтр: не покупайте актив, если его дневной RSI улетел выше 80, даже если новостной фон восторженный.

🔴 ОШИБКИ
• Продавать актив только потому, что RSI зашел выше 70: в сильном тренде перекупленность может удерживаться неделями!

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Бычья дивергенция по RSI на дневном таймфрейме часто предшествует мощному взлету котировок после затяжного падения.
''',
