📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Цена может двигаться на пустом рынке на небольших сделках, но настоящие большие деньги всегда оставляют след в виде **объемов торгов** (столбики внизу графика). Золотое правило трейдера: **Volume precedes price** («Объем идет впереди цены»). Если крупный фонд накапливает позицию перед мощным ростом, объемы торгов взрываются еще до того, как цена сдвинется с места.

📚 СЛОВАРЬ ТЕРМИНОВ
• Кумулятивный объем — суммарный объем торгов за сессию.
• Кульминация продаж (Selling Climax) — гигантский объем торгов на свече падения, означающий капитуляцию толпы и скупку активов крупным игроком (дно рынка).

🟢 КАК ИСПОЛЬЗОВАТЬ
• Пробой уровня сопротивления считается истинным и надежным только в том случае, если он сопровождается **всплеском объема торгов**. Если пробой произошел на мизерных объемах — это ложный пробой.

🔴 ОШИБКИ
• Верить пробоям уровней, которые происходят при вялых, падающих объемах.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Огромный объем торгов на зеленой свече после долгого падения — верный признак того, что крупный игрок выкупает акцию.
''',
