      readingTimeMinutes: 8,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Графические паттерны — это застывшие геометрические фигуры, которые оставляют котировки на графике в результате борьбы быков и медвежьей психологии. Знание базовых паттернов помогает заранее просчитать цели движения цены.
• **Двойное дно (W-образный разворот):** Цена дважды ударилась об один уровень поддержки и пошла вверх — сигнал разворота тренда на рост.
• **Голова и плечи (Head and Shoulders):** Главный разворотный паттерн вершины: три пика, где средний (голова) выше двух других (плечей). Пробой линии шеи вниз знаменует обвал.
• **Симметричный треугольник:** Сжатие волатильности перед мощным пробоем в какую-либо сторону.

📚 СЛОВАРЬ ТЕРМИНОВ
• Линия шеи (Neckline) — линия поддержки или сопротивления, пробой которой завершает формирование разворотной фигуры.
• Ретест — возвращение цены к пробитому уровню перед продолжением движения.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Не входите в сделку внутри фигуры. Дождитесь уверенного пробоя линии шеи или границы треугольника с подтверждением объема.

🔴 ОШИБКИ
• Видеть любимые паттерны в любом случайном зигзаге графика.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Классический ретест пробитого уровня сопротивления (который теперь стал поддержкой) — одна из самых безопасных точек входа в тренд.
''',
