      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Главное отличие профессионального трейдера от лудомана — обязательное использование **Stop-Loss (стоп-лосса)**. Стоп-лосс — это автоматический приказ брокеру: «Если акция упадет до уровня Х, немедленно продай ее, зафиксировав небольшой контролируемый убыток». Без стоп-лосса одна убыточная бумага может тянуть ваш капитал на дно месяцами.
Take-Profit, наоборот, фиксирует вашу целевую прибыль на заданном уровне сопротивления.

📚 СЛОВАРЬ ТЕРМИНОВ
• Stop-Loss — приказ на ограничение убытков.
• Take-Profit — приказ на фиксацию прибыли.
• Соотношение риск / прибыль (Risk / Reward Ratio) — пропорция между потенциальным убытком по стопу и потенциальной прибылью по тейку. Должна быть не менее 1 к 2 или 1 к 3.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Всегда выставляйте стоп-лосс сразу в момент открытия спекулятивной позиции. Не переносите стоп дальше при падении цены («надеюсь, отрастет»).

🔴 ОШИБКИ
• Торговать на бирже без стоп-лоссов в расчете на то, что «вечный инвестор пересидит любую просадку».

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Профессионалы рискуют в одной сделке не более чем 1–2% от своего общего капитала.
''',
