Правило 1% гласит: **ни в одной отдельно взятой сделке вы не должны рисковать суммой, превышающей 1% от вашего общего торгового капитала**.
Если ваш депозит составляет 300 000 рублей, ваш максимальный допустимый убыток в одной идее — 3 000 рублей. Если цена от вашего входа до стоп-лосса составляет 5%, вы рассчитываете объем покупки так, чтобы при срабатывании стопа потерять ровно 3 000 руб.

📚 СЛОВАРЬ ТЕРМИНОВ
