📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Тильт (Tilt) — состояние эмоционального аффекта и потери контроля после череды убыточных сделок, когда трейдер пытается «отыграться», заходит на все деньги с плечом и теряет остаток депозита.
Ошибка выжившего — склонность судить об успехе стратегии только по историям единичных счастливчиков, сорвавших куш на криптовалюте или мем-акциях, игнорируя 99% разорившихся лудоманов.

📚 СЛОВАРЬ ТЕРМИНОВ
• Тильт — эмоциональное расстройство, приводящее к иррациональным поступкам на рынке.
• Синдром отыгрыша — навязчивое желание немедленно вернуть потерянное любой ценой.

🟢 КАК БОРОТЬСЯ
