Алгоритмический трейдинг — это торговля по жестким математическим правилам, зашитым в код робота или скрипта (на Python, MQL или через API брокера). Робот не испытывает страха, не поддается тильту, исполняет приказы за миллисекунды и торгует 24/7 строго по чек-листу.

📚 СЛОВАРЬ ТЕРМИНОВ
• Бэктестинг (Backtesting) — проверка торговой стратегии на исторических данных за прошлые годы.
• Проскальзывание — разница между расчетной ценой робота и реальной ценой исполнения в стакане.

