      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Фьючерс — это контракт на покупку или продажу базового актива (акции, индекса, валюты, нефти) в будущем по заранее оговоренной цене. Главная особенность фьючерса — **гарантийное обеспечение (ГО)**. Чтобы купить фьючерс на нефть стоимостью 70 000 рублей, вам не нужно платить всю сумму: брокер берет с вашего счета лишь залог (ГО) в размере ~10–15% (например, 7 000 рублей). Это встроенное кредитное плечо.

📚 СЛОВАРЬ ТЕРМИНОВ
• Гарантийное обеспечение (ГО) — залог, который блокирует брокер для поддержания фьючерсной позиции.
• Экспирация — дата окончания срока жизни фьючерсного контракта, когда происходит финальный расчет.
• Вариационная маржа — ежедневная прибыль или убыток по фьючерсу, которая зачисляется или списывается с вашего счета каждый день.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Фьючерсы идеальны для хеджирования (страхования) портфеля акций от падения без необходимости продавать сами акции.

🔴 ОШИБКИ
• Торговать фьючерсами с полным плечом без понимания механики вариационной маржи — один неудачный день может обнулить счет.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Контроль размера ГО и вариационной маржи — залог выживания на срочном рынке FORTS.
''',
