      category: 'Хеджирование',
      readingTimeMinutes: 7,
      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Хеджирование — это финансовая страховка. Допустим, у вас на счете акции на 1 млн рублей, и вы ожидаете обвала рынка из-за геополитики или ставки ЦБ, но продавать любимые акции не хотите (чтобы не платить налоги или не терять дивиденды). Вы открываете **короткую позицию (шорт)** по фьючерсу на индекс Мосбиржи. Если рынок падает, ваши акции дешевеют, но фьючерс приносит прибыль, полностью компенсируя просадку портфеля!

📚 СЛОВАРЬ ТЕРМИНОВ
• Хэдж (Hedge) — защитная позиция, компенсирующая возможные убытки по основному активу.
• Шорт (Короткая позиция) — ставка на падение цены актива.

🟢 КАК ИСПОЛЬЗОВАТЬ
