      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Опцион — это контракт, дающий право (но не обязанность) купить или продать базовый актив по фиксированной цене в будущем.
• **Call (Колл):** Право купить актив по фиксированной цене (ставка на рост).
• **Put (Пут):** Право продать актив по фиксированной цене (ставка на падение / страховка).
Главная магия опционов: покупатель опциона рискует **только уплаченной премией** (стоимостью опциона), но потенциал прибыли может быть неограниченным!

📚 СЛОВАРЬ ТЕРМИНОВ
• Премия опциона — цена, которую покупатель платит продавцу за контракт.
• Страйк (Strike) — фиксированная цена исполнения опциона.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Покупка опционов Put — лучшая долгосрочная страховка от черных лебедей (катастрофических обвалов рынка).

🔴 ОШИБКИ
• Продавать опционы без обеспечения (голые продажи) — это может привести к бесконечным убыткам при резком скачке рынка.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Опционы требуют глубоких знаний математики и волатильности (модель Блэка-Шоулза).
''',
