📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Маржинальная торговля — это торговля на заемные деньги брокера («с плечом»). Если у вас есть 100 000 рублей, а вы берете плечо 1:2, вы можете купить акций на 300 000 рублей (100k своих + 200k в долг брокера). Если акция растет на 10%, вы зарабатываете 30 000 рублей (30% на свой капитал!). Но если акция падает, убытки также умножаются втрое. При падении счета до критического уровня наступает **маржин-колл**.

📚 СЛОВАРЬ ТЕРМИНОВ
• Маржин-колл (Margin Call) — требование брокера срочно пополнить счет или закрыть убыточные позиции из-за падения стоимости залога.
• Стоп-аут (Stop Out) — принудительное закрытие брокером ваших позиций по худшей рыночной цене из-за нехватки средств.

🟢 КОГДА ИСПОЛЬЗОВАТЬ
• Начинающим инвесторам **категорически запрещено** использовать маржинальные плечи.

🔴 ОШИБКИ
• Использовать плечи на волатильных акциях третьего эшелона.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Каскад маржин-коллов у физических лиц на резком падении рынка формирует идеальное «дно» для покупок.
''',
