      content: '''
📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Экономика живет циклично, как времена года:
1. **Рецессия (Спад):** Производство падает, безработица растет, ЦБ снижает ставки. (Время покупать облигации и золото).
2. **Оживление:** Спрос восстанавливается, компании начинают нанимать сотрудников. (Время покупать акции роста).
3. **Бум (Экономический пик):** Максимальная занятость, рост инфляции, ЦБ поднимает ставки. (Время фиксировать акции и уходить в флоатеры).
4. **Стагфляция:** Редкий и опасный кошмар — инфляция высокая, а экономика падает.

📚 СЛОВАРЬ ТЕРМИНОВ
• Рецессия — спад ВВП в течение двух кварталов подряд.
• Стагфляция — сочетание стагнации экономики и высокой инфляции.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Определяйте текущую фазу цикла по решениям ЦБ и данным Росстата, адаптируя структуру портфеля.

🔴 ОШИБКИ
• Покупать циклические активы в разгар рецессии в расчете на мгновенное чудо.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Смена риторики ЦБ от мягкой к жесткой сигнализирует о переходе от бума к охлаждению экономики.
''',
