📖 СУТЬ ПРОСТЫМИ СЛОВАМИ
Макроэкономические индикаторы — это приборная панель государства:
• **ВВП (Валовый внутренний продукт):** Общая стоимость всех товаров и услуг, произведенных в стране за год.
• **Безработица:** Низкая безработица — хорошо для людей, но разгоняет инфляцию зарплат, заставляя ЦБ повышать ставку.
• **Торговый баланс:** Разница между экспортом и импортом. Профицит торгового баланса укрепляет национальную валюту.

📚 СЛОВАРЬ ТЕРМИНОВ
• Профицит торгового баланса — экспорт превышает импорт (страна зарабатывает больше валюты, чем тратит).
• Дефицит торгового баланса — импорт превышает экспорт.

🟢 КАК ИСПОЛЬЗОВАТЬ
• Следите за ежемесячными релизами Минэкономразвития и ЦБ по динамике ВВП и инфляции.

🔴 ОШИБКИ
• Принимать инвестиционные решения на основе устаревших годовых отчетов без учета текущих макроданных.

🕵️ КОСВЕННЫЕ ПРИЗНАКИ
• Рост импорта при падении экспорта ухудшает торговый баланс и давит на курс национальной валюты.
''',
